window.DICTIONARY_ENTRY_SHARDS["0069-006f"]={"0069-006f:f7b78e5a0e6cac":{"word":"Ionenfalle","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·nen·fal·le","de-DE":"Io·nen·fal·le"},"forms":[{"form":"Ionenfalle","tags":["Nominativ","Singular"]},{"form":"Ionenfallen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine Vorrichtung, die Ionen, also elektrisch geladene Atome oder Moleküle, festhält, zum Beispiel um ein Zerstören der Leuchtsubstanz in einer Bildröhre zu verhindern"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus Ion und Falle"],"examples":[{"text":"Ionenfallen haben Anwendungen in der Massenspektrometrie, in der optischen Präzisions-Spektroskopie und beim Bau von Quantencomputern.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionenfalle","id":"f7b78e5a0e6cac"},"0069-006f:cd22bef3f776f7":{"word":"Iod","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Iod","de-DE":"Iod"},"forms":[{"form":"Iod","tags":["Nominativ","Singular"]},{"form":"Jod","tags":["variant"]},{"form":"Iode","tags":["Dativ","Singular"]},{"form":"Iods","tags":["Genitiv","Singular"]},{"form":"Iodes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"chemisches Element mit der Ordnungszahl 53, das zur Gruppe der Halogene gehört"}],"synonyms":["Jod"],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":["Iodat","Iodazid","Iodbromid","Iodchlorid","Iodfluorid","Iodid","Iodit","Iodmangel","Iodnitrid","Iodsäure","Iodstickstoff","Iodunverträglichkeit","Iodwasserstoff","Iodwasserstoffsäure"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Iod","id":"cd22bef3f776f7"},"0069-006f:c3ff88785cca4e":{"word":"Iowa","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Iowa","de-DE":"Iowa"},"forms":[{"form":"IA","tags":["Kurzform"]},{"form":"Iowas","tags":["Genitiv","Singular"]},{"form":"des Iowa","tags":["Genitiv","Singular"]},{"form":"des Iowas","tags":["Genitiv","Singular"]},{"form":"(das) Iowa","tags":["Nominativ","Singular"]},{"form":"(dem) Iowa","tags":["Dativ","Singular"]}],"senses":[{"definition":"Bundesstaat im Mittleren Westen der USA"}],"synonyms":[],"origins":["der Name stammt letztlich vom indigenen Volk der Iowa/Ioway in der Sprache Chiwere, einem Seitenzweig der Sioux-Sprachfamilie; es wird vermutet, dass der Name von ayuxba „Schläfrige“ aus dem Dakota entlehnt wurde"],"examples":[{"text":"Mein Mann kommt aus Iowa.","reference":""},{"text":"Iowa ist für seine weiten Naturlandschaften bekannt, aber auch für seine dörfliche und kleinstädtische Natur.","reference":"Iowa. Amerika-Live.de, abgerufen am 15. Dezember 2011."},{"text":"Man nennt Iowa nicht ohne Grund den Corn State, denn nirgendwo anders wird soviel Mais angebaut wie hier.","reference":""},{"text":"„Er hat den Laden übernommen, und aus unserer Korrespondenz weiß ich, dass er als einer von nur drei Studenten das Taxonomiestudium in Iowa erfolgreich abgeschlossen hat.“","reference":"Jo Nesbø: Minnesota. Kriminalroman. 3. Auflage. Ullstein, Berlin 2026 (übersetzt von Günther Frauenlob), ISBN 978-3-550-20309-1, Seite 404."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Iowa","id":"c3ff88785cca4e"},"0069-006f:7eb0077ea672f4":{"word":"IOK","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"IOK","de-DE":"IOK"},"forms":[],"senses":[{"definition":"Internationales Olympisches Komitee"}],"synonyms":["International Olympic Commitee","Internationales Olympisches Komitee","IOC"],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"IOK","id":"7eb0077ea672f4"},"0069-006f:23e06f08a5a3a9":{"word":"Ion","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ion","de-DE":"Ion"},"forms":[{"form":"Ion","tags":["Nominativ","Singular"]},{"form":"Ions","tags":["Genitiv","Singular"]},{"form":"Ionen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"elektrisch geladenes Teilchen, das aus einem neutralen Atom oder Molekül durch Anlagerung oder Abgabe von Elektronen (Ionisation) entsteht"}],"synonyms":[],"origins":["Entlehnung aus dem Englischen vom Substantiv ion ^(→ en), das auf altgriechisch ἰόν (ion^☆) ^(→ grc) „Gehendes, Wanderndes“, 1. Partizip Neutrum vom Verb ἰέναι (ienai^☆) ^(→ grc) „gehen“ zurückgeht; also eigentlich „wanderndes Teilchen“, wie es sich beispielsweise bei der elektrochemischen Spaltung chemischer Verbindungen zu den Elektroden hinbewegt; der Begriff wurde vom englischen Physiker und Chemiker Michael Faraday ^(→ WP) (1791 bis 1867) geprägt."],"examples":[{"text":"Dieses Ion ist zweifach positiv geladen.","reference":""},{"text":"„Weder gibt es einen Plus- noch einen Minuspol, sondern nur ein Gefälle von geladenen Teilchen wie Elektronen oder Ionen.“","reference":"Daniel Scholten: Denksport Deutsch. Wer hat bloß die Gabel zur Frau und den Löffel zum Mann gemacht?. dtv, München 2016, ISBN 978-3-423-26134-0, Seite 40."},{"text":"[…] „Beim Lösen eines Salzes muss zunächst die Gitterenergie aufgewendet werden, um die Anziehungskräfte zwischen den Ionen im Kristallgitter zu überwinden und die Ionen voneinenader zu trennen.“","reference":"Wolfgang Asselborn (Hrsg.): Chemie heute – Sekundarbereich I. Westermann Schroedel Diesterweg Schöningh Winklers GmbH, Braunschweig 2020, ISBN 978-3-507-88009-2, Seite 206"},{"text":"„Manche Ionen binden ihre Hydrathülle so fest, dass beim Auskristallisieren des Salzes ein Teil der Wasser-Moleküle in das Kristallgitter eingebaut wird.“","reference":""}],"idioms":[],"collocations":[],"derivations":["ionisch","Ionenantrieb","Ionenaustausch","Ionenaustauscher","Ionenbeschleuniger","Ionenbindung","Ionenfalle","Ionenfleck","Ionengitter","Ionenkanal","Ionenladung","Ionenlawine","Ionenquelle","Ionenreaktion","Ionenspektrum","Ionenstrahl","Ionentherapie","Ionentriebwerk","Ionenverbindung","Ionenwanderung","Ionisation","Ionisierung","Ionium","Ionometer","Ionophorese","Ionosphäre","ionisieren"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ion","id":"23e06f08a5a3a9"},"0069-006f:f65eddd8757557":{"word":"Ionisches Meer","partOfSpeech":"Wortverbindung","gender":"das","hyphenation":{"de-CH":"Io·ni·sches Meer","de-DE":"Io·ni·sches Meer"},"forms":[{"form":"Ionischem Meer","tags":["Dativ","Singular"]},{"form":"Ionisches Meer","tags":["Nominativ","Singular"]},{"form":"Ionischen Meeres","tags":["Genitiv","Singular"]},{"form":"das Ionische Meer","tags":["Nominativ","Singular"]},{"form":"dem Ionischen Meer","tags":["Dativ","Singular"]},{"form":"ein Ionisches Meer","tags":["Nominativ","Singular"]},{"form":"des Ionischen Meeres","tags":["Genitiv","Singular"]},{"form":"einem Ionischen Meer","tags":["Dativ","Singular"]},{"form":"eines Ionischen Meeres","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ein Teil des Mittelmeeres südlich der Adria zwischen Süditalien und Griechenland"}],"synonyms":[],"origins":[],"examples":[{"text":"Korfu ist eine Insel im Ionischen Meer.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisches Meer","id":"f65eddd8757557"},"0069-006f:2fc4c2562c8af2":{"word":"ionisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"io·nisch","de-DE":"io·nisch"},"forms":[{"form":"jon.","tags":["alternative"]},{"form":"ionisch","tags":["Positiv"]},{"form":"jonisch","tags":["alternative"]},{"form":"ionische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ionischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ionischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ionischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"ionisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist ionisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ionisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ionisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind ionisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"alte Kirchentonart"},{"definition":"die Landschaft Ionien oder die Kultur der Ionier betreffend"}],"synonyms":["Ionen..."],"origins":["[1] ungeklärt","[2] abgeleitet von dem historischen Toponym Ionien (Ein in der Antike von Griechen besiedeltes kleinasiatisches Küstengebiet einschließlich der Inseln Chios und Samos)"],"examples":[{"text":"Die Kirchentonarten ionisch (sowie hypoionisch, äolisch, hypoäolisch) wurden durch H. Glarean 1547 dem System der acht klassischen Kirchentonarten angegliedert.","reference":""},{"text":"Die Kirchentonart ionisch kommt der Skala des modernen C-Dur sehr nahe.","reference":""},{"text":"Er bestieg in Pydna ein ionisches Schiff und machte sich auf die Reise ins Perserreich.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"ionisch","id":"2fc4c2562c8af2"},"0069-006f:a7caa8695beade":{"word":"ionotrop","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"io·notrop","de-DE":"io·notrop"},"forms":[{"form":"ionotrop","tags":["Positiv"]},{"form":"ionotrope","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ionotropem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ionotropen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ionotroper","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"ionotropes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist ionotrop","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ionotrop","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ionotrop","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind ionotrop","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"Wirkungsweise bestimmter Rezeptoren der Zellmembran, bei Aktivierung Ionenkanäle in der Zellmembran zu öffnen"}],"synonyms":[],"origins":["Kompositum aus Ion und griechisch τρόπος (trópos) = „auf diese Art“, also in etwa: „durch Ionen wirkend“"],"examples":[{"text":"Ionotrope Rezeptoren bestehen aus membranständigen Proteinuntereinheiten, die extrazelluläre Bindungsdomänen für ihre jeweiligen Liganden besitzen und einen Ionenkanal bilden.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ionotrop","id":"a7caa8695beade"},"0069-006f:c850d03997ac76":{"word":"Ionosphäre","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·no·sphä·re","de-DE":"Io·no·sphä·re"},"forms":[{"form":"Ionosphäre","tags":["Nominativ","Singular"]},{"form":"Ionosphären","tags":["Nominativ","Plural"]}],"senses":[{"definition":"äußerste Schicht der Atmosphäre eines Himmelskörpers (meist der Erde), die durch Sonnenstrahlung Ionen und freie Elektronen enthält"}],"synonyms":[],"origins":["Kompositum aus Ion und Sphäre"],"examples":[{"text":"„Die Ionosphäre — jene Schicht, die zwischen 80 und 500 Kilometern unseren Planeten umgibt — ist bis heute so gut wie unerforscht.“","reference":"Leo Nitschmann: Erde, Meer und Atmosphäre. In: Zeit Online. Nummer 19/1957, 9. Mai 1957, ISSN 0044-2070 (URL, abgerufen am 15. Februar 2013) ."},{"text":"„Diesmal wird die besondere Aufmerksamkeit der Himmelsforscher verschiedenen noch wenig ergründeten Phänomenen gelten, die sich vor allem in der Ionosphäre und der oberen Atmosphäre abspielen.“","reference":"H. E.: Das Jahr der Ruhigen Sonne. In: Zeit Online. Nummer 22/1961, 26. Mai 1961, ISSN 0044-2070 (URL, abgerufen am 15. Februar 2013) ."},{"text":"„Denn hier in Polnähe trifft der wechselnde Sonnenwind besonders intensiv auf die Erde, beeinflusst die Ionosphäre – und möglicherweise auch das Klima.“","reference":"Hans Schuh: Ruf des Nordens. Arktis. In: Zeit Online. Nummer 37/2009, 3. September 2009, ISSN 0044-2070 (URL, abgerufen am 15. Februar 2013) ."}],"idioms":[],"collocations":[],"derivations":["ionosphärisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionosphäre","id":"c850d03997ac76"},"0069-006f:51fc76efab1544":{"word":"Io","partOfSpeech":"Eigenname","gender":"die","hyphenation":{"de-CH":"Io","de-DE":"Io"},"forms":[{"form":"Ios","tags":["Genitiv","Singular"]},{"form":"der Io","tags":["Genitiv","Singular"]},{"form":"(der) Io","tags":["Dativ","Singular"]},{"form":"(die) Io","tags":["Nominativ","Singular"]}],"senses":[{"definition":"drittgrößter Mond Jupiters"}],"synonyms":[],"origins":["Benannt nach Io, in der griechischen Mythologie eine Geliebte des Zeus (Zeus entspricht dem römischen Jupiter). Io ist daher – wie die Venus – weiblich („die Io“)."],"examples":[{"text":"Io wurde von Galileo Galilei entdeckt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Io","id":"51fc76efab1544"},"0069-006f:de1b6beb809d03":{"word":"iodhaltig","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"iod·hal·tig","de-DE":"iod·hal·tig"},"forms":[{"form":"iodhaltig","tags":["Positiv"]},{"form":"iodhältig","tags":["variant"]},{"form":"jodhaltig","tags":["variant"]},{"form":"iodhaltige","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"iodhaltigem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"iodhaltigen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"iodhaltiger","tags":["Komparativ"]},{"form":"iodhaltiges","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"iodhaltigere","tags":["Komparativ","Nominativ","strong","Singular","feminine"]},{"form":"iodhaltigste","tags":["Superlativ","Nominativ","strong","Singular","feminine"]},{"form":"iodhaltigerem","tags":["Komparativ","Dativ","strong","Singular","masculine"]},{"form":"iodhaltigeren","tags":["Komparativ","Genitiv","strong","Singular","masculine"]},{"form":"iodhaltigerer","tags":["Komparativ","Nominativ","strong","Singular","masculine"]},{"form":"iodhaltigeres","tags":["Komparativ","Nominativ","strong","Singular","neuter"]},{"form":"iodhaltigstem","tags":["Superlativ","Dativ","strong","Singular","masculine"]},{"form":"iodhaltigsten","tags":["Superlativ","Genitiv","strong","Singular","masculine"]},{"form":"iodhaltigster","tags":["Superlativ","Nominativ","strong","Singular","masculine"]},{"form":"iodhaltigstes","tags":["Superlativ","Nominativ","strong","Singular","neuter"]},{"form":"am iodhaltigsten","tags":["Superlativ"]},{"form":"er ist iodhaltig","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist iodhaltig","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist iodhaltig","tags":["Positiv","predicative","Singular","feminine"]},{"form":"er ist iodhaltiger","tags":["Komparativ","predicative","Singular","masculine"]},{"form":"es ist iodhaltiger","tags":["Komparativ","predicative","Singular","neuter"]},{"form":"sie sind iodhaltig","tags":["Positiv","predicative","Plural"]},{"form":"sie ist iodhaltiger","tags":["Komparativ","predicative","Singular","feminine"]},{"form":"sie sind iodhaltiger","tags":["Komparativ","predicative","Plural"]},{"form":"er ist am iodhaltigsten","tags":["Superlativ","predicative","Singular","masculine"]},{"form":"es ist am iodhaltigsten","tags":["Superlativ","predicative","Singular","neuter"]},{"form":"sie ist am iodhaltigsten","tags":["Superlativ","predicative","Singular","feminine"]},{"form":"sie sind am iodhaltigsten","tags":["Superlativ","predicative","Plural"]}],"senses":[{"definition":"Jod enthaltend"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"iodhaltig","id":"de1b6beb809d03"},"0069-006f:cc423d4fab43ce":{"word":"Iota","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Iota","de-DE":"Iota"},"forms":[{"form":"Ι","tags":["symbol","uppercase"]},{"form":"Iota","tags":["Nominativ","Singular"]},{"form":"Jota","tags":["alternative"]},{"form":"Iotas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"neunter Buchstabe des griechischen Alphabets; entspricht dem lateinischen »i«"},{"definition":"das Allerkleinste, das Allergeringste"}],"synonyms":[],"origins":["über gotisch jōta ^(→ got) von altgriechisch ἰῶτα (iōta^☆) ^(→ grc), nach der gotischen Bibelübersetzung von Matthäus 5, 18"],"examples":[{"text":"Vermutlich wird er leider kein Iota von seiner ursprünglichen Meinung abrücken.","reference":""},{"text":"„Obwohl die griechische Vorlage der gotischen Bibelübersetzung gar nicht erhalten ist, lässt sie sich bis aufs Iota aus der gotischen Übersetzung rekonstruieren.“","reference":"Daniel Scholten: Denksport Deutsch. Wer hat bloß die Gabel zur Frau und den Löffel zum Mann gemacht?. dtv, München 2016, ISBN 978-3-423-26134-0, Seite 193 f."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Iota","id":"cc423d4fab43ce"},"0069-006f:62d92b6dce0ce6":{"word":"Ionisationsröhre","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·röh·re","de-DE":"Io·ni·sa·ti·ons·röh·re"},"forms":[{"form":"Ionisationsrohr","tags":["variant"]},{"form":"Ionisationsröhre","tags":["Nominativ","Singular"]},{"form":"Ionisationsröhren","tags":["Nominativ","Plural"]}],"senses":[{"definition":"dünnes Glasrohr mit innerer Anode, äußerer Kathode, mit einseitiger Abschlusskappe zur Ionisation von Luft"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Röhre, mit dem Fugenelement -s"],"examples":[{"text":"„Die Patentschrift aus dem Jahre 1984 beschreibt eine Ionisationsröhre als eine hülsenförmige Innenelektrode innenwandnah erstreckt, während eine hülsenförmige Aussenelektrode auf der Aussenfläche der Isolatorröhre aufgeschoben und gegenüber der Innenelektrode verschiebbar ist.“","reference":"Patent CH 666372 A5 Espacenet.com, Erfinder: Conrad John Habicht, Eingetragen 20.07.1984, abgerufen am 29.05.2013"},{"text":"„Die Erfindung betrifft ein Luftreinigungsgerät mit einer Ionisationsröhre, die an der Sekundärseite eines Hochspannungstransformators angeschlossen ist und die von zu reinigender Luft umströmt wird, wobei der Hochspannungstransformator primärseitig mit einer Ansteuerschaltung zur Erzeugung einer sekundärseitig oszillierenden Hochspannung angesteuert wird.“","reference":"DE10111445A1 12.09.2002 auf patent-de.com PatentDe-Luftreinigungsgerät, Erfinder:Schröder, Werner, abgerufen am 19. Juni 2013"},{"text":"„Die durch Filter gereinigt Luft wird an der Ionisationsröhre vorbeigeleitet (die Ionisationsröhre hat die Form wie eine Leuchtstoffröhre) und damit wird die Luft ionisiert.“","reference":"FAQ - häufige Fragen. In: IDI Luftreinigung, Luftreinigungsgeräte. Abgerufen am 23. Mai 2013."},{"text":"„Luftreinigungsgerät nach einem der Ansprüche 1ä5, dadurch gekennzeichnet, dass die Ionisationsröhre aus einem Glasrohr besteht, dessen Innenwandung mit einem Aluminiumblech als erste Elektrode ausgekleidet ist und dessen Außenwandung mit einem Drahtgewebe als zweite Elektrode umgeben ist, wobei zwischen der ersten Elektrode und der zweiten Elektrode die sekundärseitig oszillierende Hochspannung anliegt.“","reference":"Ventilation system for interior of vehicle has ionization tube housing with air inlet and outlet mounted with its air inlet side in front of at least one ventilation slit. Abgerufen am 23. Mai 2013."},{"text":"„Ionisationstechnik von BENTAX mit Ionisationsröhren zur Luftaufbereitung, Entkeimung, Geruchsneutralisation und Schadstoffabbau in jedem Gebäude und jeder Lüftungsanlage.“","reference":"Ionisationsröhre von BENTAX zur Luftaufbereitung. Abgerufen am 23. Mai 2013."},{"text":"„Je nach Anwendungsfall (Luftbeschaffenheit, Intensitätsstufe, Einschaltdauer) hält eine bioclimaticTM Ionisationsröhre 1-3 Jahre.“","reference":"Fehlender Parameter (Hilfe) In: Aircom - innovative Lüftungsanlagen Berlin GmbH. Abgerufen am 23. Mai 2013."},{"text":"„CONE (COmbined sensor for Neutrals and Electrons = Kombinierter Sensor zur Messung des Neutralgases und von Elektronen) ist eine Kombination aus einer Ionisationsröhre und einer fest vorgespannten Langmuirsonde.“","reference":"CONE Instrument PR, Leibniz-Institut für Atmosphärenphysik e.V, abgerufen am 19. Juni 2013"},{"text":"„Die strahlungsfreie Ionisationsröhre besitzt eine Isolatorröhre, in deren Innenraum sich eine hülsenförmige Innenelektrode, Anode aus Edelstahl) befindet, während eine hülsenförmige Außenelektrode, Kathode aus Edelstahl) auf der Außenfläche der Isolatorglasröhre aufgeschoben ist.“","reference":"Einsatz eines alternativen Abluftreinigungsverfahrens (PDF; 793kB), Technische Universität Darmstadt-Fachgebiet Abfalltechnik, abgerufen am 08. Juli 2013"},{"text":"„An Ionisierungsstäben, Aufladestäben und Ionisationsröhren kann der Schutz gegen elektrischen Schlag auch durch Einhaltung der Grenzwerte für Strom, Ladung oder Energie nach DIN EN 61010-1 erfüllt werden“","reference":"Grundsätze für die Prüfung und Zertifizierung von Ionisierungssystemen (PDF; 216kB), Berufgenossenschaft HVBG, abgerufen am 08. Juli 2013"}],"idioms":[],"collocations":[],"derivations":["Ionisationsröhrengitter","Ionisationsröhrenhalterung","Ionisationsröhrenhersteller","Ionisationsröhrensockel","Ionisationsröhrentyp"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsröhre","id":"62d92b6dce0ce6"},"0069-006f:a7a147827bd352":{"word":"Ionisationsgerät","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·ge·rät","de-DE":"Io·ni·sa·ti·ons·ge·rät"},"forms":[{"form":"Ionisationsgerät","tags":["Nominativ","Singular"]},{"form":"Ionisationsgeräte","tags":["Nominativ","Plural"]},{"form":"Ionisationsgeräts","tags":["Genitiv","Singular"]},{"form":"Ionisationsgeräten","tags":["Dativ","Plural"]},{"form":"Ionisationsgerätes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Gerät zur Ionisation der Luft, des Wassers oder von Stoffen basierend auf einem Ionisator"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Ionisation und Gerät mit dem Fugenelement -s"],"examples":[{"text":"„Es gibt zahlreiche externe und interne Steuer- und Regelsysteme für Ionisationsgeräte mit Ionisationsröhren, die mit Betriebsspannung von 1,5–2,85 kV auf der Ionisationsröhre betrieben werden.“","reference":"Wikipedia-Artikel „Ionisationsröhre“ (Stabilversion)"},{"text":"„Die Ionisation mit unseren Ionisationsgeräten sorgt für klare, saubere Luft, die maßgeblich das Raumklima verbessert.“","reference":"raumluftkonzept.de www.raumluftkonzept.de - Handelsvertreter AC-Umwelttechnik, abgerufen am 22. Mai 2013"},{"text":"„Unser Ionisationsgerät lässt sich bei gleichzeitiger Bestellung in unsere Trocknungsgeräte mit Gebläse optimal integrieren.“","reference":"Ionisationsgerät zur Luftverbesserung. In: Steurer Ionisationsgerät zur Luftverbesserung. Abgerufen am 22. Mai 2013."},{"text":"„Der EI Form ist ein Ionisationsgerät, das sich konvex und konkav gekrümmten Oberflächen anpassen lässt.“","reference":"Ionisationssystem zur elektrostatischen Entladung www.haug.de, abgerufen am 03. Juli 2013"},{"text":"„Der Abstand vom Zielobjekt und die Ventilatorgeschwindigkeit beeinflussen das Leistungsvermögen des Ionisationsgerätes.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 22. Mai 2013."},{"text":"„Die zuverlässigen und kostengünstigen Netzgeräte PU55 und PU80 erzeugen die Hochspannung für den Betrieb der Ionisationsgeräte der Blue Label Baureihe.“","reference":"Entladesystem - Wiederstandsgekoppeltes Hochleistungsionisationssystem, www.dr-escherich.de - Dr. Escherich GmbH, abgerufen am 05. Juli 2013"},{"text":"„An der Wand gegenüber der Tür wurde ein Wasserfall mit einem Ionisationsgerät untergebracht.“","reference":"Der Wasserfall mit einem Ionisationsgerät. In: Salzhütten, Stimmungsvoller Innenraum, segensreichen Einfluss auf unseren Körper. Abgerufen am 22. Mai 2013."}],"idioms":[],"collocations":[],"derivations":["Hochleistungsionisationsgerät"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsgerät","id":"a7a147827bd352"},"0069-006f:ed66750d820d9f":{"word":"Ionenverbindung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·nen·ver·bin·dung","de-DE":"Io·nen·ver·bin·dung"},"forms":[{"form":"Ionenverbindung","tags":["Nominativ","Singular"]},{"form":"Ionenverbindungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Stoff, der durch Ionenbindung zusammengehalten wird"}],"synonyms":["Salz"],"origins":["zusammengesetzt aus Ionen, dem Plural von Ion, und Verbindung"],"examples":[{"text":"„Ionenverbindungen haben meist hohe Schmelz- und Siedetemperaturen.“","reference":"Fehlender Parameter (Hilfe) In: superlehrer.de. Abgerufen am 12. April 2013."},{"text":"„Als Formelmasse (früher Formelgewicht) bezeichnet man bei einer Ionenverbindung die Summe der Atommassen der verhältnismäßig am Aufbau beteiligten Atome.“","reference":"Wikipedia-Artikel „Formelmasse“ (Stabilversion)"},{"text":"„Natriumhydrid (NaH) ist das Hydrid des Natriums, also eine Ionenverbindung, in der Wasserstoff negativ geladen ist und Natrium positiv.“","reference":"Wikipedia-Artikel „Natriumhydrid“ (Stabilversion)"},{"text":"„In festem Zustand leiten Ionenverbindungen den elektrischen Strom nicht. […] Schmelzen oder wässrige Lösungen von Ionenverbindungen leiten den elektrischen Strom.“","reference":"chemie-master.de"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ionenverbindung","id":"ed66750d820d9f"},"0069-006f:ef00a05f567edd":{"word":"Ionisation","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·on","de-DE":"Io·ni·sa·ti·on"},"forms":[{"form":"Ionisation","tags":["Nominativ","Singular"]},{"form":"Ionisierung","tags":["variant"]},{"form":"Ionisationen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"die Entfernung eines oder mehrerer Elektronen aus einem Atom oder Molekül durch Energiezufuhr oder auch deren Anlagerung"}],"synonyms":["Bildung von Ionen","Ionisierung"],"origins":["von gleichbedeutend englisch ionization ^(→ en), zu ionize ^(→ en) gebildet"],"examples":[{"text":"Natürliche Ionisation entsteht durch kosmischen Strahlung, der Strahlung radioaktiven Stoffe, der Sonnenstrahlung oder physikalischer Natureffekte wie am Wasserfall","reference":""},{"text":"„Unter Ionisation versteht man die Erzeugung freier Elektronen und positiv geladener Atome - also Ionen.“","reference":"Ionisation''lp.uni-goettingen.de, abgerufen am 15. August 2013"},{"text":"„Unter Ionisation versteht man den Vorgang, aus elektrisch neutralen Atomen oder Molekülen positiv und negativ geladene Teilchen, also I.-Paare zu bilden“","reference":"umweltlexikon-online.deUmweltlexikon.de, abgerufen am 29.05.2013"},{"text":"„Die Ionisation auf dem elektronischem Wege erfolgt so: Nach dem Prinzip der Koronaentladung wird naszierender Sauerstoff erzeugt, d. h. die Spaltung von Sauerstoffmolekülen O2 in die beiden Sauerstoffatome O* mit pos. oder neg. Ladung, die ein erhöhtes Energie- und Ladungspotenzial aufweisen.“","reference":"IonisierungsvorrichtungPatentDe DE102005059327A1 27.07.2006, abgerufen am 14. Juli 2013"},{"text":"„Durch künstliche Ionisation […] kann die natürliche Konzentration an negativen Luftionen wiederhergestellt werden.“","reference":"Was Sie über Luftionen wissen sollten!www.fitsein.de, abgerufen am 14. Juni 2013"}],"idioms":[],"collocations":[],"derivations":["ionisieren","Ionisator","Ionisationsanlage","Ionisationsapparat","Ionisationsapparatur","Ionisationsbereich","Ionisationsdetektor","Ionisationsdichte","Ionisationseffekt","Ionisationselektrode","Ionisationsenergie","Ionisierungsenthalpie","Ionisationsereignis","Ionisationsfaktor","Ionisationsfilter","Ionisationsfolge","Ionisationsgas","Ionisationsgerät","Ionisationsgleichgewicht","Ionisationskammer","Ionisationsleistung","Ionisationslinie","Ionisationsmechnanismus","Ionisationsmelder","Ionisationsmessröhre","Ionisationsmessung","Ionisationsmethode","Ionisationsmodul","Ionisationspotential","Ionisationspotenzial","Ionisationsprozess","Ionisationsrauchmelder","Ionisationsregler","Ionisationsröhre","Ionisationsspannung","Ionisationsstab","Ionisationssteuerung","Ionisationsstrom","Ionisationsstufe","Ionisationssystem","Ionisationstechnik","Ionisationstrafo","Ionisationsüberwachung","Ionisationsverfahren","Ionisationsvermögen","Ionisationsvorgang","Ionisationsvorrichtung","Ionisationszeit"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ionisation","id":"ef00a05f567edd"},"0069-006f:552765d3fcbf25":{"word":"Ionisierung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sie·rung","de-DE":"Io·ni·sie·rung"},"forms":[{"form":"Ionisierung","tags":["Nominativ","Singular"]},{"form":"Ionisierungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Entfernung oder Hinzufügung eines oder mehrerer Elektronen zu einem Atom oder Molekül"},{"definition":"Technisches Gerät mit einem Ionisator, der die Ionisierung der Luft herbeiführt"}],"synonyms":["Bildung von Ionen","Ionisation"],"origins":["Derivation, des Verbs ionisieren und dem Suffix -ung, Suffigierung"],"examples":[{"text":"„Bringt man ionisierte Luft zwischen entgegengesetzt geladene Konduktoren (Elektroden), so verlieren beide an Ladung, d. h. es entsteht, wenn diese fortwährend ergänzt wird und auch die Ionisierung etwa durch Einwirkung von Radiumstrahlen konstant erhalten wird, ein dauern der Strom, wie beim Einbringen der Elektroden in einen Elektrolyten.“","reference":"Ionisierung der Luft www.zeno.org, abgerufen am 18. Dezember 2013"},{"text":"„Die Ionisierung führt insbesondere zu einer Verringerung von Küchengerüchen, indem die organischen Moleküle aus der Luft entfernt werden.“","reference":"Wohlbefinden für den Organismusfalmec Deutschland GmbH, abgerufen am 19. Juni 2013"},{"text":"„Für eine Sauenaufzuchtanlage mit einer Anlage zu Ionisierung der Stallluft sollten die Belastungen der Stallluft sowie der unbehandelten und behandelten Luft erhoben werden.“","reference":"Bestimmung der Keimemission und der Wirksamkeit der Luftionisation(PDF; 988 kB), Sächsisches Landesamt für Umwelt und Geologie, abgerufen am 08. Juli 2013"},{"text":"„In einer Ausgestaltung hat die erfindungsgemäße Ionisierungsvorrichtung zur Ionisierung von Luft den Vorteil, dass sie elektrisch mit einer Lampenfassung verbunden werden kann.“","reference":"IonisierungsvorrichtungPatentDE DE102005059327A1 27.07.2006, abgerufen am 14. Juli 2013"}],"idioms":[],"collocations":[],"derivations":["ionisieren","Ionisierungseffekt","Ionisierungseinheit","Ionisierungsenergie","Ionisierungsfall","Ionisierungsspektrum","Ionisierungsstab","Ionisierungssystem","Ionisierungstechnik","Ionisierungseinrichtung","Ionisierungsgerät","Ionisierungsmittel","Ionisierungspotential","Ionisierungsprozess","Ionisierungsverfahren","Ionisierungsvermögen","Ionisierungsvorrichtung","Ionisierungszustand"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ionisierung","id":"552765d3fcbf25"},"0069-006f:7eb823251e513e":{"word":"ionisieren","partOfSpeech":"Verb","gender":"","hyphenation":{"de-CH":"io·ni·sie·ren","de-DE":"io·ni·sie·ren"},"forms":[{"form":"haben","tags":["Hilfsverb","Perfekt"]},{"form":"ionisier!","tags":["Imperativ","Singular"]},{"form":"ionisiere","tags":["Präsens"]},{"form":"ionisiert","tags":["Präsens"]},{"form":"ionisiere!","tags":["Imperativ","Singular"]},{"form":"ionisieren","tags":["Aktiv","Infinitiv","Präsens"]},{"form":"ionisierst","tags":["Präsens"]},{"form":"ionisiert!","tags":["Imperativ","Plural"]},{"form":"ionisierte","tags":["Präteritum"]},{"form":"ionisierend","tags":["Partizip","Präsens","Aktiv"]},{"form":"du ionisierst","tags":["2. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ich ionisiere","tags":["1. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ihr ionisiert","tags":["2. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"zu ionisieren","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"du ionisierest","tags":["2. Person","Singular","Präsens","Aktiv","Konjunktiv I"]},{"form":"ich ionisierte","tags":["1. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr ionisieret","tags":["2. Person","Plural","Präsens","Aktiv","Konjunktiv I"]},{"form":"ionisiert sein","tags":["statal-passive","Infinitiv","Präsens"]},{"form":"sie ionisieren","tags":["3. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"wir ionisieren","tags":["1. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"du ionisiertest","tags":["2. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"habe ionisiert!","tags":["Imperativ","uncommon","2. Person","Singular","Perfekt","Aktiv"]},{"form":"habt ionisiert!","tags":["Imperativ","uncommon","2. Person","Plural","Perfekt","Aktiv"]},{"form":"ihr ionisiertet","tags":["2. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"ionisieren Sie!","tags":["Imperativ","Höflichkeitsform","Präsens","Aktiv"]},{"form":"ionisiert haben","tags":["Aktiv","Infinitiv","Perfekt"]},{"form":"sie ionisierten","tags":["3. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"wir ionisierten","tags":["1. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"zu ionisierende","tags":["Partizip","gerundive"]},{"form":"ionisiert werden","tags":["Vorgangspassiv","Infinitiv","Präsens"]},{"form":"zu ionisierender","tags":["Partizip","gerundive"]},{"form":"du hast ionisiert","tags":["2. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"ionisiert zu sein","tags":["statal-passive","erweitert","Infinitiv"]},{"form":"ich habe ionisiert","tags":["1. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"ihr habt ionisiert","tags":["2. Person","Plural","Perfekt","Aktiv","Indikativ"]},{"form":"ionisiert zu haben","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"sie sind ionisiert","tags":["3. Person","Plural","Präsens","statal-passive","Indikativ"]},{"form":"zu ionisierendes …","tags":["Partizip","gerundive"]},{"form":"du habest ionisiert","tags":["2. Person","Singular","Perfekt","Aktiv","Konjunktiv I"]},{"form":"du wirst ionisieren","tags":["2. Person","Singular","Futur I","Aktiv","Indikativ"]}],"senses":[{"definition":"ein oder mehrere Elektronen zu einem Atom oder Molekül hinzufügen oder entfernen und damit den elektrischen Ladungszustand verändern"}],"synonyms":[],"origins":["etymologisch: von gleichbedeutend englisch ionize ^(→ en), aus altgriechisch ἰέναι (ienai^☆) ^(→ grc) „gehen“","strukturell: Derivation (Ableitung) zum Substantiv Ion mit dem Derivatem (Ableitungsmorphem) -ier und der Flexionsendung -en"],"examples":[{"text":"„Diese energetischen geladenen Teilchen können das Zählgas eines Detektors, eine Art moderner Geigerzähler, ionisieren.“","reference":"Th. Wilpert, Ch. Schulz: Neutronennachweis. Abgerufen am 19. Mai 2013."},{"text":"Dagegen werden wir Neutronenstrahlen, die sehr wohl ionisieren, nicht als ionisierende Strahlung bezeichnen, weil ihre Hauptwirkung im Anstoßen von Atomkernen besteht, die ihrerseits ionisieren; die Ionisation ist dann ein sekundärer Prozess.","reference":"Herbert Daniel: Physik. Atome, Festkorper, Kerne, Teilchen. Band 4, Walter de Gruyter, 1998, ISBN 9783110146318, Seite 289 (alte Schreibweise im Zitat: ‚Prozeß‘, zitiert nach Google Books) ."},{"text":"Bei Strahlung ionisieren Alpha- und Betateilchen die Atome der von ihnen durchquerten Substanzen und erzeugen meist Kationen.","reference":"Chris Oxlade, Jane Wertheim: Tessloffs Schülerlexikon Biologie, Chemie, Physik. TESSLOFF Verlag, 2007, ISBN 9783788614669, Seite 320 (zitiert nach Google Books) ."},{"text":"Auch Gammastrahlen können Atome ionisieren.","reference":""},{"text":"Die Gasatome vermögen durch ihre eigene kinetische Energie andere durch Stoß zu ionisieren (Stoßionisation).","reference":"Ekbert Hering, Rolf Martin, Martin Stohrer: Physik für Ingenieure. 11. Auflage. Springer DE, 2012, ISBN 9783642225697, Seite 310 (zitiert nach Google Books) ."}],"idioms":[],"collocations":[],"derivations":["ionisierend","ionisiert","Ionisation","Ionisator","Ionisieren","Ionisierung"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ionisieren","id":"7eb823251e513e"},"0069-006f:9a53d58a105ca5":{"word":"Ionisierkopf","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sier·kopf","de-DE":"Io·ni·sier·kopf"},"forms":[{"form":"Ionisierkopf","tags":["Nominativ","Singular"]},{"form":"Ionisierkopfe","tags":["Dativ","Singular"]},{"form":"Ionisierkopfs","tags":["Genitiv","Singular"]},{"form":"Ionisierköpfe","tags":["Nominativ","Plural"]},{"form":"Ionisierkopfes","tags":["Genitiv","Singular"]},{"form":"Ionisierköpfen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Vorrichtung zur elektrostatischen Entladung über größere Distanzen"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus dem Stamm des Verbs ionisieren und dem Substantiv Kopf"],"examples":[{"text":"„Mit DC-Ionisierköpfen wird der geschnittene Papierstapel nach dem Schneidmesser entladen, damit eine störungsfreie Ablage auf dem Papiertisch möglich ist.“","reference":"Ionisierkopf - Spengler Electronic AGSpengler AG, abgerufen am 21. Mai 2013"},{"text":"„Vorrichtung nach Anspruch 16, dadurch gekennzeichnet, daß die Entladestation (9) von einem mit mehreren Elektrodenspitzen (10) versehenen Ionisierkopf (12) gebildet ist, wobei die Elektrodenspitzen von einer Wechselhochspannung von etwa 5 KV gespeist werden.“","reference":"Patent EP0941742 A2 - Internetverweis Patentschrift, abgerufen am 21. Mai 2013"},{"text":"„Durch die offene Bauweise des Ionisierkopfes und die Luftstromverstärkerdüse weist die 4110 eine marktführende Wirksamkeit auf: maximale Ionisierung und maximaler Luftstrom.“","reference":"4110 IONENSPRÜHPISTOLE. In: Fraser Anti-Static. Abgerufen am 21. Mai 2013."},{"text":"„Die in dem BH50 Ionisierkopf eingebaute antistatische Stäbe nutzen die Effekte der Luftausbreitung und der Ionisierung gleichzeitig aus, um einen ionisierenden Luftstreifen zu generieren, mit dem elektrostatische Ladungen auch über große Entfernungen neutralisiert werden können.“","reference":"Ionisierkopf BH50. In: ACE electrostatic, Geräte, Entladung. Abgerufen am 21. Mai 2013."},{"text":"„Das Modell 935 besteht aus einem Ionisierkopf und einem integrierten Ventilatorsystem.“","reference":"935 Ionisiergebläse. In: Meech Produkte. Abgerufen am 21. Mai 2013."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisierkopf","id":"9a53d58a105ca5"},"0069-006f:159e444edc9bc1":{"word":"Ionisationsstab","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·stab","de-DE":"Io·ni·sa·ti·ons·stab"},"forms":[{"form":"Ionisationsstab","tags":["Nominativ","Singular"]},{"form":"Ionisationsstabe","tags":["Dativ","Singular"]},{"form":"Ionisationsstabs","tags":["Genitiv","Singular"]},{"form":"Ionisationsstäbe","tags":["Nominativ","Plural"]},{"form":"Ionisationsstabes","tags":["Genitiv","Singular"]},{"form":"Ionisationsstäben","tags":["Dativ","Plural"]}],"senses":[{"definition":"Stab, der zur punktuellen Ionisation von kleinsten Bauteilgruppen dient"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Stab, mit dem Fugenelement -s"],"examples":[{"text":"„1265 Einzelpunkt Ionisationsstab Leistungsstarker Punkt-Ionisator. Dieser Ionisationsstab ist ideal zur Ionisation von kleinen Teilen in kompakter Bauweise. […]“","reference":"Hersteller-Website IONPulseIONPulse Limited, abgerufen am 21. Mai 2013"},{"text":"„Der Ionisationsstab EI DC eignet sich hervorragend für den Einsatz in schnell laufenden Prozessen oder zum Neutralisieren von hohen elektrostatischen Ladungen.“","reference":"Ionisationsgerät EI DC. In: Haug Ionisationsgeräte. Abgerufen am 21. Mai 2013."},{"text":"„Der Ionisationsstab IO RN ist ein leistungsstarkes und robustes Gerät zur Beseitigung elektrostatischer Aufladungen und hat sich bei Folien-Paternostern und Panel Cleaner hervorragend bewährt.“","reference":"Ionisationsstab IO RN für Paternoster und Panel Cleaner. In: Gottschild made in Germany - Ideen und Systeme für mehr Effektivität in der Möbelindustrie. Abgerufen am 21. Mai 2013."},{"text":"„Ein handelsüblicher Ionisationsstab besitzt zur gleichmäßigen Verteilung der hohen Spannung symmetrisch angeordnete, nur sehr kleine, zylindrische Elektroden mit einem Durchmesser von ca. 1 mm, die in einem isolierenden Material eines Halters so eingesetzt sind, daß die Elektrode nur ca. 2 bis 4 mm vorsteht.“","reference":"Fehlender Parameter (Hilfe) In: EUROPÄISCHE PATENTANMELDUNG, Woop, Heiko. Abgerufen am 21. Mai 2013."},{"text":"„Mit dem Ionisator verhindert der Ionisationsstab Störeinflüsse beim automatischen Einwiegen mit dem 864 Balance Sample Processor.“","reference":"Fehlender Parameter (Hilfe) In: Metrohm Deutschland. Abgerufen am 21. Mai 2013."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsstab","id":"159e444edc9bc1"},"0069-006f:bba2214f954188":{"word":"Ionisator","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sa·tor","de-DE":"Io·ni·sa·tor"},"forms":[{"form":"Ionisator","tags":["Nominativ","Singular"]},{"form":"Ionisators","tags":["Genitiv","Singular"]},{"form":"Ionisatoren","tags":["Nominativ","Plural"]}],"senses":[{"definition":"ein technisches Teil oder Gerät, das Ionisation bewirkt"}],"synonyms":[],"origins":["Derivation des Verbs ionisieren mit dem Suffix -ator zum Nomen, Suffigierung"],"examples":[{"text":"„Geräte zur Ionisierung, bei denen die erzeugten Ionen in Gasen ein Plasma erzeugen (siehe Ionenquellen, Sputtern, Plasma, Plasmatron und Plasmaschneiden) sind nicht Gegenstand dieses Artikels, da sie zwar prinzipiell auch Ionisatoren sind, jedoch nicht so bezeichnet werden. “","reference":"Ionisator www.Chemie.deCHEMIE.DE Information Service GmbH, abgerufen am 26.05.2013"},{"text":"„Ionisatoren sind dagegen üblicherweise Geräte zur Ionisierung von Luft oder Wasser oder sie geben Ionen gerichtet auf Oberflächen ab. Sie dienen z. B. der Ladung oder Entladung von Materialien und Partikeln, oder die entstehenden freien Radikale fördern chemische Abbauprozesse (Geruchsbeseitigung, Desinfektion).“","reference":"Ionisierung von Luft oder WasserCHEMIE.DE Information Service GmbH-Ionisator, abgerufen am 26.05.2013"},{"text":"„…Ionisatoren arbeiten mit Hochspannung und einer Koronaentladung, oder… “","reference":"Ionisatoren mit KoronaentladungWikipedia Ionisationsröhre, abgerufen am 26.05.2013"},{"text":"„Aus den durchgeführten Messungen geht hervor, dass bei den gegebenen Arbeitsbedingungen die Ozonkonzentation in dem, den Ionisator durchfließenden Sauerstoff, um 30 ppm geringer ist als in durchschnittlicher Luft; des weiteren waren keine Stickoxide mehr nachweisbar“","reference":"Der Einfluss der Elektrizität (neg. Ionen) der Luft auf den Organismus(PDF; 90kB), saechsische-schweiz-touristik.de, abgerufen am 23. Juli 2013"}],"idioms":[],"collocations":[],"derivations":["Ionisatorleistung","Ionisatorspannung"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisator","id":"bba2214f954188"},"0069-006f:2f21fce7939897":{"word":"Ionisationstechnik","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·tech·nik","de-DE":"Io·ni·sa·ti·ons·tech·nik"},"forms":[{"form":"Ionisator","tags":["Kurzform"]},{"form":"Ionisationstechnik","tags":["Nominativ","Singular"]},{"form":"Ionisationstechniken","tags":["Nominativ","Plural"]}],"senses":[{"definition":"technisches Gerät oder Einrichtung zur Ionisation der Luft, von Gasen, Stoffen oder von Wasser; Methode"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Technik, sowie dem Fugenelement -s"],"examples":[{"text":"„Ionisationstechnik: Matrix-Assisted-Laser-Desorption-Ionisation (MALDI) mittels 337 nm Stickstoff-Laser“","reference":"Instrumentelle Ausstattung im Institut für Chemie der Universität Kassel - Ultraflex der Firma Bruker Daltonics Uni-Kassel, abgerufen am 26. Mai 2013"},{"text":"„In der Entwicklung befinden sich prozessanalytische Anwendungen der modernen massenspektrometrischen Methoden (Ionenfalle, Time-of-Flight und Ionisationstechniken für flüssige und feste Proben).“","reference":"Spektroskopische Methoden für die ProzessanalytikPR - Wiley-VCH Verlag GmbH&Co.KGaA, Ausgabe: 18.02.2013, abgerufen am 18. Juni 2013"},{"text":"„Die Antwort lautet: Ionisationstechnik.“","reference":"Küchenplaner MagazinPR-STROBEL VERLAG GmbH & Co. KG, 44. Jahrgang (2010), abgerufen 19. Juni 2013"},{"text":"„Die Kombination von UV-Technik mit der Ionisationstechnik wird in der Lüftungstechnik seit Ende der 1990er Jahre zur Abluft- und Raumluftaufbereitung verwendet.“","reference":"IonisationsgerätWikipedia.org, abgerufen am 12. August 2013"},{"text":"„Die Ionisationstechnik kann in Zusammenhang mit einem sehr schnell scannenden Massenanalysator vielfältig Einsatz finden.“","reference":"Resonanzverstärkte MehrphotonenionisationWikipedia.org, abgerufen am 12. August 2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationstechnik","id":"2f21fce7939897"},"0069-006f:9db882c911610e":{"word":"Ionometer","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·no·me·ter","de-DE":"Io·no·me·ter"},"forms":[{"form":"Ionometer","tags":["Nominativ","Singular"]},{"form":"Ionometern","tags":["Dativ","Plural"]},{"form":"Ionometers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Ionen-Messgerät zur Bestimmung der Ionenkonzentration in der Luft"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus dem Substantiv Ion und dem Suffix -meter, mit dem Fugenelemente -o"],"examples":[{"text":"Mit einem Ionometer lassen sich positiv und negativ geladen Ionenkonzentrationen in der Luft bestimmen.","reference":""},{"text":"„Im Vergleich zur Außenluft ließ sich in der Stollenluft ein höherer Ionisationsgrad, gemessen mit Ionometer, nachweisen.“","reference":"Information zur Stollentherapie in Berchtesgaden. Abgerufen am 27. Mai 2013.(PDF; 114KB), Seite 1"},{"text":"„Luftionen stellen aufgrund Ihrer geringen elektrischen Ladung hohe technische Anforderungen an das Ionometer, dem Messgerät zur Messung der Ionenkonzentration.“","reference":"Das Ionometer IM806 zur kontinuierlichen Messung der Luftionenkonzentration. Umweltanalytik Holbach GmbH, abgerufen am 27. Mai 2013."},{"text":"„Ionometer sind für die Detektion von Radon-Auffälligkeiten ebenfalls geeignet: Hohe Kleinionenzahlen in der Raumluft korrelieren oft mit radioaktiver Strahlung und vor allem mit der Radonkonzentration und der Anzahl der Zerfallsnuklide.“","reference":"Messung der Radonkonzentration(PDF; 132kB)BAUBIOLOGIE MAES/IBN, abgerufen am 29. Juli 2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionometer","id":"9db882c911610e"},"0069-006f:6d82691e0357c5":{"word":"Ionisierungsvorrichtung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sie·rungs·vor·rich·tung","de-DE":"Io·ni·sie·rungs·vor·rich·tung"},"forms":[{"form":"Ionisierungsvorrichtung","tags":["Nominativ","Singular"]},{"form":"Ionisierungsvorrichtungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Vorrichtung zur Luftbehandlung in Anlagen oder zum Schadstoffabbau in beaufschlagenden Räumen; Ionisator"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Ionisierung und Vorrichtung mit dem Fugenelement -s"],"examples":[{"text":"„ Ionisierungsvorrichtung für Luftbehandlungsanlagen mit zwei Elektroden, die mit einer eine Wechselspannung erzeugenden Hochspannungsquelle verbindbar sind “","reference":"Internetquelle: Patent, Ionisierungsvorrichtung No. EP 2376231 A1, Erfinder: Manfred H. Langner,Veröffentlichungsdatum: 19. Okt. 2011, abgerufen 30.05.2013"},{"text":"„Erfindungsgemäß ist vorgesehen, dass ein Behälter […] als integrierte Ionisierungseinrichtung und einer Ionisierungsvorrichtung bereitgestellt wird.“","reference":"Internetquelle: Patent, Ionisierungsvorrichtung DE102005059327A1 27.07.2006, Erfinder: Stechel, Günther, abgerufen 30.05.2013"},{"text":"„Verfahren zur Ansteuerung einer Ionisierungsvorrichtung (7), insbesondere einer Ionisierungsvorrichtung (7) zur Ionisierung von Luft (L) zur Belüftung von Innenräumen (5), bevorzugt von Kraftfahrzeuginnenräumen (5), wobei die Ionisierungsvorrichtung (7) zumindest zeitweise (14) Ionen (8) eines ersten Ionentyps (8) freisetzt, […]“","reference":"Internetquelle: Patent,Ionisierungsvorrichtung EP 2467273 A1 27. Juni 2012, Antragsteller:\nBehr GmbH & Co. KG, abgerufen 30.05.2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisierungsvorrichtung","id":"6d82691e0357c5"},"0069-006f:92f4653572ee79":{"word":"Ionengenerator","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·nen·ge·ne·ra·tor","de-DE":"Io·nen·ge·ne·ra·tor"},"forms":[{"form":"Ionengenerator","tags":["Nominativ","Singular"]},{"form":"Ionen-Generator","tags":["alternative"]},{"form":"Ionengenerators","tags":["Genitiv","Singular"]},{"form":"Ionengeneratoren","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Gerät bestehend aus einem Ionisator und einer Hochspannungsquelle zur Erzeugung von Koronaentladungen in Luft oder einem technischen Gas"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ion und Generator, sowie dem Fugenelement -en"],"examples":[{"text":"„Die Standardisierung von Generator- und Mess-Ausrüstungen durch eine unabhängige Autorität würde den hastigen und bedauernswerten Trend, Ionengeneratoren von fragwürdiger Sicherheit, Qualität und Ausstoß zu vermarkten, beenden.“","reference":"Negative Ionen–Vitamine der Luft?(PDF; 987kB), Autoren: Don Strachan and J.Karnstedt, Übersetzt a.d Engl. durch Baeck GmbH&Co.KG in 01/205, abgerufen am 07. Juni 2013"},{"text":"„Ionengenerator […] der geregelt so viele negative und positive Ionen in der Zuluft erzeugt, dass das Ionenverhältnis (negative/positive Ionen) wieder dem der Außenluft entspricht (Niveau ca. 2000 Ionen/cm3, Verhältnis zugunsten neg. Ionen ca. 1,5/1).“","reference":"Ionengenerator - Typisierung(PDF 1,4MB),Lucerne University, Ausgabe Januar 2013 - S.21, abgerufen am 30. Mai 2013"},{"text":"„Ionengenerator mit einer Nadelelektrode und einer Masseelektrode, die mit der Nadelelektrode zusammenwirken kann, um zum Produzieren von Ionen eine Koronaentladung in der Luft zu erzeugen, wobei die Masseelektrode derart angeordnet ist, dass sie eine imaginäre Verlängerung einer Längsachse der Nadelelektrode umgibt, dadurch gekennzeichnet, dass ein Teil der Masseelektrode entleert ist, um eine darin ausgebildete Spaltregion zu bilden.“","reference":"Ionengenerator Patent, Antragsteller: Matsushita Electric Works Ltd., Eingetragen: 24. Nov. 2001, abgerufen am 30. Mai 2013"},{"text":"„Einrichtung zur Elektroklimatisierung des Innenraumes eines Kraftfahrzeuges […] in dem Frischluft Einlaßkanal ein Ionengenerator angeordnet ist; […]“ Patent:","reference":"Ionengenerator''Patent, Antragsteller: HAUFE,Paul,J.,M., Eingetragen: 14.Juli 1988, abgerufen am 02. Juni 2013"},{"text":"„Ein Ionengenerator, der ein Ionenerzeugungselement in einem Gehäuse beherbergt, wobei das Ionenerzeugungselement eine Entladungsnadelelektrode und eine Masseelektrode, die der Entladungsnadelelektrode zugewandt ist, aufweist, wobei der Ionengenerator Folgendes umfasst: […]“","reference":"Ionengenerator German Patent DE112008000228, Antragsteller: Murata Mfg. Co., Ltd., abgerufen am 02. Juni 2013"},{"text":"„Positive oder negative Iongenerator im Gasmedium mit Plasmaeinschluss“","reference":"Ionengenerator''Patent, Erfinder: Breton, Jacques Leon Georges, Pessac Gironde, FR, Anmeldung:20.07.1995, abgerufen am 02. Juni 2013"},{"text":"„Ein Klimagerät besteht aus einem Gebläse mit druckseitig angeordnetem Ionengenerator und einem zuströmseitig vom Ionengenerator angeordneten elektrischen Staubabscheider.“","reference":"IonengeneratorPatent, Erfinder: Till Keesmann,Eingetragen:31. Juli 1986, abgerufen am 02.06.2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionengenerator","id":"92f4653572ee79"},"0069-006f:29aab82bd14467":{"word":"Ionenkonzentration","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·nen·kon·zen·tra·ti·on","de-DE":"Io·nen·kon·zen·tra·ti·on"},"forms":[{"form":"Ionenkonzentration","tags":["Nominativ","Singular"]},{"form":"Ionenkonzentrationen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Gehalt an Ionen in einem flüssigen/gasförmigen Medium"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ion und Konzentration sowie dem Fugenelement -en"],"examples":[{"text":"„Es ist offensichtlich, dass bei zunehmender Ionenkonzentration auch die Menge der pro Zeiteinheit transportierbaren Ladungen steigt, bzw. die elektrische Leitfähigkeit der Ionenkonzentration proportional ist.“","reference":"Theorie der Leitfähigkeit. Abgerufen am 3. Juni 2013."},{"text":"„Ionenzähler müssen sorgfältig benutzt werden: Innerhalb eines Raums variiert die Ionenkonzentration beträchtlich abhängig davon, wie weit man vom Ionen-Generator entfernt ist […].“","reference":"Fachaufsatz Negative Ionen–Vitamine der Luft?, PDF, Don Strachan and Jim Karnstedt, Übersetzt aus dem Englischen durch Baeck GmbH&Co.KG, 01/2005, abgerufen 07. Juni 2013"},{"text":"„Erhöhte Ionendichte ergab sich bei bewölktem Himmel und Schneefall, Regen und Nebel verursachten niedrige Ionenkonzentrationen.“","reference":"Ergebnisse einer bioklimatologischen Analyse der positiven und negativen Kleinionen in einigen Tunnelsystemen Kärntens und Salzburgs PDF, abgerufen 18. Juni 2013"}],"idioms":[],"collocations":[],"derivations":["Ionenkonzentrationsmessung","Kleinionenkonzentration","Wasserstoffionenkonzentration","Sauerstoffionenkonzentration","Wasserstoff-Ionenkonzentration","Sauerstoff-Ionenkonzentration"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionenkonzentration","id":"29aab82bd14467"},"0069-006f:92913eb118535a":{"word":"Ionisationssensor","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·sen·sor","de-DE":"Io·ni·sa·ti·ons·sen·sor"},"forms":[{"form":"Ionisationssensor","tags":["Nominativ","Singular"]},{"form":"Ionisationssensors","tags":["Genitiv","Singular"]},{"form":"Ionisationssensoren","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Messfühler"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Sensor, mit Fugenelement -s"],"examples":[{"text":"„Ionisationssensor mit einer fadenförmigen Anode, einem zylindrischen Kollektor und einer Elektronenquelle, angeordnet zwischen der Anode und dem Kollektor […]“","reference":"Ionisationssensor mit Mikropunktkathode Patent EP 0662607 B1, Erfinder: Robert Baptist, Eingetragen: 9. Januar 1995, abgerufen am 03. Juni 2013"},{"text":"„Ionisationssensor im Zündsystem einer Brennkraftmaschine.“","reference":"Ionisationssensor im Zündsystem einer Brennkraftmaschine Patent EP0922857A1+A2, Erfinder: RENAULT, Eingetragen: 12.Dezember 1997, abgerufen am 03. Juni 2013"},{"text":"„Ionisationssensoren bieten die Möglichkeit zum umfassenden ESD-Monitoring inklusive problemloser Einbindung in bestehende Monitoringsysteme.“","reference":"ESD Management > Produktneuheiten > Ionisationssensor 3150 www.pmt.eu, abgerufen am 05. August 2013, Schreibfehler korrigiert"},{"text":"„Der Brenner ist mit einem Ionisationssensor im Flammenbereich versehen und wird durch mindestens zwei unterschiedliche Gase gespeist.“","reference":"Verfahren zur Bestimmung einer Luftzahl bei einem Brenner Patent EP1817814 B1, Erfinder: Christian Hoffmann, Philipp Klose, Lutz Schilling, Eingetragen: 08. Dezember 2005, abgerufen am 10. August 2013"},{"text":"„Die OTI – Multisensormelder, bestehend aus einem optischen Rauchsensor (O-Teil), einem Thermosensor (T-Teil) und einem Ionisationssensor (I-Teil).“","reference":"Automatische Melder - Multisensormelder OTI www.enco-gera.de, abgerufen am 10 August 2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationssensor","id":"92913eb118535a"},"0069-006f:774dbe3dd933fe":{"word":"Ionisationsbipolröhre","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·bi·pol·röh·re","de-DE":"Io·ni·sa·ti·ons·bi·pol·röh·re"},"forms":[{"form":"Ionisationsbipolröhre","tags":["Nominativ","Singular"]},{"form":"Bipol-Ionisationsröhre","tags":["alternative"]},{"form":"Ionisationsbipolröhren","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Glaskolben mit zwei Abschlusskappen; innen Anode und außen Kathode"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Bipolröhre, sowie dem Fugenelement -s"],"examples":[{"text":"Eine Ionisationsröhre der bekannten Bauart, mit 1x Abschlusskappe, gibt es auch mit 2x Abschlusskappen und wird als Bipol, also Ionisationsbipolröhre bezeichnet.","reference":""},{"text":"„4er Pack Ionisationsbipolröhre Typ A (Bipolionisationsröhre Typ A) Art.-Nr.: IR-A-070 / M4-6mm Länge: 70mmGewindezapfen: 2 x M4-6mm Hochleistungsröhre mit 24-48.000h Betriebsstunden Ausführung: Longlife durch Edelstahl, Lieferung: direkt ab Werk.“","reference":"4er Pack Ionisationsbipolröhre (PDF; 450kB), www.Spezilamp.de, abgerufen am 17. Juli 2013"},{"text":"„Ionisationsbipolröhren mit zwei Abschlusskappen an einem Stück Glasrohr, werden beidseitig gelagert und verfügen sowohl über einen Anodenanschluss als auch über einen Kathodenanschluss.“","reference":"Wikipedia-Artikel „Ionisationsröhre“, abgerufen am 17. Juli 2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsbipolröhre","id":"774dbe3dd933fe"},"0069-006f:33f5965f89eb39":{"word":"Ionisationsleistung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·leis·tung","de-DE":"Io·ni·sa·ti·ons·leis·tung"},"forms":[{"form":"Ionisationsleistung","tags":["Nominativ","Singular"]},{"form":"Ionengehalt, Ionendichte","tags":["variant"]}],"senses":[{"definition":"elektrische Leistung an einem Ionisator zur Erzeugung von Ionen"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Leistung, sowie dem Fugenelement -s"],"examples":[{"text":"„Produktmerkmale wie bei Modell 725 aber mit zusätzlicher Ionisation. Ionisationsleistung: 200.000 bis 400.000 Ionen/cm³. Die Ionisation erzeugt eine reinigende Wirkung der Luft, […] mit einer Ionen-Nadel ausgerüstet, welche Negativ-Ionen millionenfach an die Umwelt abgibt.“","reference":"Produktbeschreibung und Nadelionisatorwww.airtechanika.de, abgerufen am 13. Juni 2013"},{"text":"„Die Wechselspannung wird in Form von Rechteckimpulsen mit einer Frequenz z.B. im Bereich von 50 Hz an die Elektroden der Ionisationsröhre angelegt. Die Steuerung der Ionisationsleistung, d.h. der Menge der erzeugten Luftionen und der Ozonmoleküle, wird dadurch gesteuert, dass die Dauer der Rechteckimpulse und deren Abstand verändert wird (Tastverhältnis). An der Ionisationsröhre liegt damit entweder keine Spannung an oder eine bestimmte fest eingestellte Hochspannung, z.B. 1,5 kV.“","reference":"Toilettenausstattung mit einem WC-BeckenPatentDe DE202004012065U1 19.01.2006 - Villeroy & Boch AG, 66693 Mettlach, abgerufen am 14. Juni 2013"},{"text":"„Das Ionisationsmodul „I” bildet, zusammen mit dem Sauerstoffkonzentrator Précise 6000 M, eine komplette Behandlungseinheit zur ionisierten Sauerstoff-Inhalationstherapie. […] Ionisationsspannung: 3,5 kV, Ionisationsleistung: ca. 5 Mio negative Ionen/cm³“","reference":"Sauerstoffkonzentratorwww.hoherz.de, abgerufen am 13. Juni 2013"},{"text":"„Die Ionisationsleistung wird in einem elektrischen Steuergerät in Abhängigkeit von den durch Sensoren ermittelten Werten entweder aufgrund der oxidierbaren Luftbestandteile in der zu behandelnden Luft oder der relativen Luftfeuchte oder der Strömungsgeschwindigkeit der Luft geregelt.“","reference":"Anordnung zur Aufbereitung von Luft in lufttechnischen Anlagenwww.freepatentsonline.com/DE10013841B4, abgerufen am 09. August"},{"text":"„Hochwertiges 24 Volt-System zur Wasserionisation mit max. 60 W Ionisationsleistung zur Durchführung von hydrogalvanischen Bädern („Detox-Bäder“).“","reference":"Profi-System der Luxusklasse.www.ionicmed.com, abgerufen am 09. August 2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsleistung","id":"33f5965f89eb39"},"0069-006f:1e53b59e177887":{"word":"Ionisierungsenergie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sie·rungs·en·er·gie","de-DE":"Io·ni·sie·rungs·en·er·gie"},"forms":[{"form":"Ionisierungsenergie","tags":["Nominativ","Singular"]},{"form":"Ionisierungsenergien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Energie elektrischer oder chemischen Art, die benötigt wird, um aus einem Atom oder Molekül, Elektronen von gasartigen Atomen Ionen zu entfernen"},{"definition":"Energie, die einem atomaren System zugeführt werden muss, um es in einen angeregten Energiezustand zu bringen"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisierung und Energie, Fugenelement -s"],"examples":[{"text":"„Die Ionisierungsenergie I eines Atoms, ist die Mindestenergie, die notwendig ist, um diesem Atom ein Elektron komplett zu entreissen.“","reference":"Ionisierungsenergie ChemGlob.org, abgerufen am 29. Juni 2013"},{"text":"„Die Ionisierungsenergie stellt ein direktes Maß für den Energiezustand des betreffenden Elektrons dar - sie ist um so kleiner, je höher dessen Energie ist - und ist eine der wenigen grundlegenden Eigenschaften eines Atoms, die der direkten Messung zugänglich sind.“","reference":"Periodensystem-Erste Ionisierungsenergie Rutherford - Uniterra.de, abgerufen am 05. Juli 2013"},{"text":"„Die Energie, welche benötigt wird um ein Elektron vom Atom oder Molekül zu trennen wird als Ionisierungsenergie bezeichnet. Die vor der Ionisierungsenergie ausgeglichene Ladungsdifferenz zwischen Atomkern und Elektronenhülle wird durch das Entfernen des Elektrons zu einer positiven elektrischen Ladung.“","reference":"Chemische Elemente geordnet nach der Ionisierungenergie. www.lenntech.de, abgerufen am 14. August 2013"},{"text":"„Die Energie, die man benötigt, um ein Elektron aus einem Atom zu entfernen, nennt man Ionisierungsenergie.“","reference":"Ionen und Ionisierungsenergie www.u-helmich.de - Chemie Klasse 9 > Atombau, abgerufen am 14. August 2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisierungsenergie","id":"1e53b59e177887"},"0069-006f:05c70cc2e2bed6":{"word":"Ionisationsanlage","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·an·la·ge","de-DE":"Io·ni·sa·ti·ons·an·la·ge"},"forms":[{"form":"Ionisationsanlage","tags":["Nominativ","Singular"]},{"form":"Ionisationsanlagen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Einrichtung, die zur Ionisierung eines Mediums dient oder auch Gruppe von Ionisationsgeräten"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Anlage, mit dem Fugenelement -s"],"examples":[{"text":"„Das Abgas wird von einem Ventilator durch einen Feststofffilter angesaugt und in die Ionisationsanlage gefördert.“","reference":"Einsatz eines alternativen Abluftreinigungsverfahrens (PDF; 2,8 MB) www.fachdokumente.lubw.baden-wuerttemberg.de, abgerufen am 20. Dezember 2013"},{"text":"„Bei dieser Ionisationsanlage sind mehrere Vorrichtungen zur Ionisation von gasförmigem Sauerstoff, insbesondere von Sauerstoff in Raumluft, insbesondere mehrere Vorrichtungen der zuvor erläuterten Art, nebeneinander, aber mit Abstand voneinander angeordnet.“","reference":"Vorrichtung zur Ionisation von gasförmigem Sauerstoff und Ionisationsanlage mit solchen Vorrichtungen www.patent-de.com, DE3702337C3, abgerufen am 20. Dezember 2013"},{"text":"„PMT Partikel-Messtechnik bietet seinen Kunden einen umfassenden Beratungs- und Wartungsservice für die PMT Ionisationsanlagen an.“","reference":"Anwendung von Ionisationssystemen www.pmt.eu, abgerufen am 20. Dezember 2013"},{"text":"„Die Ionisationsanlage wird mit Frischluft aus dem Außenbereich des Sudhauses versorgt.“","reference":"GEA - Einsatz der Ionisationsanlage (PDF; 204 KB) www.geabrewery.de, abgerufen am 20. Dezember 2013"},{"text":"„Aus diesem Grund ist es notwendig dem Reinigungsvorgang eine Ionisationsanlage vorzuschalten, welche eine elektrostatisch neutrale Oberfläche gewährleistet und somit ein leichtes Lösen der Partikel ermöglicht.“","reference":"Effektive Bahnentstaubung - Statische Aufladung (PDF; 325 KB) www.kunststoff-schweiz.ch, abgerufen am 20. Dezember 2013"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsanlage","id":"05c70cc2e2bed6"},"0069-006f:dcea47b62da71f":{"word":"Ionisationskammer","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·kam·mer","de-DE":"Io·ni·sa·ti·ons·kam·mer"},"forms":[{"form":"IC","tags":["Kurzform"]},{"form":"IK","tags":["Kurzform"]},{"form":"Ionisationskammer","tags":["Nominativ","Singular"]},{"form":"Ionisationskammern","tags":["Nominativ","Plural"]}],"senses":[{"definition":"für Ionisationsvorgänge vorgesehener Raum in einer technischen Anlage in dem Ionisationsgeräte wirken"},{"definition":"mit Gas befülltes Gerät zum Messen der Strahlungsstärke radioaktiver Stoffe mit Hilfe der von ihnen erzeugten Ionen"},{"definition":"Gerät zur Erzeugung und Nachweis von Röntgenstrahlen; Funktionsweise einer Röntgenröhre"},{"definition":"Kammer, in der Strahlung zu therapeutischen Zwecken erzeugt und gezielt eingesetzt wird"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Kammer, mit dem Fugenelement -s"],"examples":[{"text":"Die Ionisationskammer in einem Lüftungsgerät ist zumeist eine Leerteil oder die Umluft-/Mischluftkammer in die die Ionisationsgeräte, zur Ionisation der Luft, eingebaut werden.","reference":""},{"text":"„Eine der ältesten Detektoren für ionisierende Strahlen ist die Ionisationskammer.“","reference":"Ionisationskammer www.rapp-instruments.de, abgerufen am 4. Januar 2014"},{"text":"„Dieses reichert sich in dem Behälter an und kann mit Hilfe eines kleinen Ventilators leicht von dem Thoriumsalz abgetrennt und in die Ionisationskammer geblasen werden.“","reference":"Schüler-Labor / Ionisationskammer(PDF; 22 MB) www-alt.gsi.de, abgerufen am 4. Januar 2014"},{"text":"„Röntgenstrahlung kann auch in einer Ionisationskammer nachgewiesen werden, wobei hier nur die durch Strahlung erzeugte Ionenmenge gemessen wird.“","reference":"Nachweis von Röntgenstrahlung - Ionisationskammer(PDF; 366 KB) abgerufen am 5. Januar 2014"},{"text":"„Weitere Untersuchungen wurden angestellt, um eine geeignete Flüssigkeit als sensitives Medium der Ionisationskammer zu finden.“","reference":"System zur Online-Qualitätssicherung in der Strahlentherapie.(PDF; 4,1 MB) abgerufen am 5. Januar 2014"}],"idioms":[],"collocations":[],"derivations":["Ionisationskammerbauart","Ionisationskammersystem","Ionisationskammertür"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationskammer","id":"dcea47b62da71f"},"0069-006f:b0e3a3f0fbbfcd":{"word":"Ionisierungsprozess","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sie·rungs·pro·zess","de-DE":"Io·ni·sie·rungs·pro·zess"},"forms":[{"form":"Ionisierungsprozeß","tags":["obsolete"]},{"form":"Ionisierungsprozesse","tags":["Nominativ","Plural"]},{"form":"Ionisierungsprozessen","tags":["Dativ","Plural"]},{"form":"Ionisierungsprozesses","tags":["Genitiv","Singular"]}],"senses":[{"definition":"eine durch Energiezufuhr ausgelöste Folge von Aktivitäten, Reaktionen und/oder Zuständen, die in einem energielosen Endzustand mündet"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisierung und Prozess, mit dem Fugenelement -s"],"examples":[{"text":"„Bei einer Mindestenergie der Elektronen („Appearance-Potential“) setzt der Ionisierungsprozess ein und durchläuft je nach Gasart bei 50…150 eV ein Maximum.“","reference":"Quadrupol-Massenspektrometer(PDF; 198 KB) www.tu-chemnitz.de, abgerufen am 7. Januar 2014"},{"text":"„Glorit ist ein Zusatzstoff aus anorganischen Salzen, der in Verbindung mit dem gewählten Ausgangsmaterial einen Ionisierungsprozess initiiert und eine Versteinerung des Materials bewirkt.“","reference":"Material für den ökologischen Wegebau(PDF; 607 KB) www.fundu.de, abgerufen am 7. Januar 2014"},{"text":"„Das zur Partialdruckmessung eingesetzte Quadrupol-Massenspektrometer ist grundsätzlich ein Ionisationsvakuummeter, allerdings mit einer zusätzlichen Einrichtung, dem Stabsystem, welche die beim Ionisierungsprozess entstandenen Ionenarten zuerst nach ihrem Masseadungsverhältniss (m/e) trennt, bevor sie mit einem Ionen-Detektor nachgewiesenwerden.“","reference":"Grundlagen der Massenspektrometrie(PDF 1,9 MB) www.physik.uni-kl.de, abgerufen am 7. Januar 2013"},{"text":"„Dieser Ionisierungsprozess führt zu einer besseren Benetzbarkeit und damit zu einer besseren Adhäsion der zu verklebenden Stellen.“","reference":"Beschläge kleben statt schrauben(PDF; 457 KB) www.fraubrunnen.com, abgerufen am 7. Januar 2014"},{"text":"„Bei einem zweiten Ionisierungsprozess durch Röntgenstrahlung wird in dem obigen Experiment eine Geschwindigkeitsänderung eines Oltropfchens […] bei einer Kondensatorspannung von 300V beobachtet.“","reference":"Vorlesung Atom- und Molekülphysik(PDF; 374 KB) www.uni-kassel.de, abgerufen am 7. Januar 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisierungsprozess","id":"b0e3a3f0fbbfcd"},"0069-006f:cf9b34072ab0c1":{"word":"Ionisieren","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·ni·sie·ren","de-DE":"Io·ni·sie·ren"},"forms":[{"form":"Ionisieren","tags":["Nominativ","Singular"]},{"form":"Ionisierens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ionisieren von Luft, Wasser und anderen Stoffen durch einen Ionisator oder natürlicher Vorgänge"}],"synonyms":[],"origins":["Derivation (Ableitung) des Verbs ionisieren durch Konversion"],"examples":[{"text":"„Die vorliegende Erfindung betrifft einen Ionisator-Satelliten (100) zum Ionisieren eines Luftstroms, wobei der Ionisator-Satellit (100) eine negative Elektrode (102) aufweist, die von dem Luftstrom anströmbar ist.“","reference":"Ionisator-Satellit zum Ionisieren eines Luftstroms Patent DE 102012220501 A1, abgerufen am 4. Januar 2014"},{"text":"„Beim Ionisieren entsteht auch bei heutigen Geräten Ozon.“","reference":"Ionisieren von Raumluft www.stadt-zuerich.ch, abgerufen am 4. Januar 2014"},{"text":"„Innovative Systemtechniken vom Bürsten, Glätten, Schleifen, Wischen, Polieren, Strukturieren, dem Entstauben und Ionisieren, der Beflammung bis zur Reinigung mit CO2 Schneestrahlen gewährleisten die qualitativ hochwertige Beschichtung.“","reference":"Vorbehandlung und Reinigung www.venjakob.de, abgerufen am 4. Januar 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisieren","id":"cf9b34072ab0c1"},"0069-006f:ea94aa0c5a725b":{"word":"Ionisationssystem","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·sys·tem","de-DE":"Io·ni·sa·ti·ons·sys·tem"},"forms":[{"form":"Ionisationssystem","tags":["Nominativ","Singular"]},{"form":"Ionisationssysteme","tags":["Nominativ","Plural"]},{"form":"Ionisationssystems","tags":["Genitiv","Singular"]},{"form":"Ionisationssystemen","tags":["Dativ","Plural"]}],"senses":[{"definition":"ein technisches System, das etwas ionisiert, um etwas zu laden/entladen oder um Schadstoffe abzubauen"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und System, mit dem Fugenelement -s"],"examples":[{"text":"„Das Streulichtsystem und das Ionisationssystem sind in derselben Ebene auf einer gemeinsamen Grundplatte angeordnet.“","reference":"Brandmelder mit einem Streulicht- und einem Ionisationssystem www.google.kz, abgerufen am 8. April 2014"},{"text":"„HAUG entwickelt und produziert Ionisationssysteme zur Beseitigung und Erzeugung elektrostatischer Aufladungen.“","reference":"HAUG BIEL AG www.kunststoff-schweiz.ch, abgerufen am 8. April 2014"},{"text":"„Die Gebläseluft in Kombination mit bewährten Ionisationssystemen ermöglicht eine höchst effektive Beseitigung von elektrostatischen Ladungen über große Abstände zum Objekt.“","reference":"Kombination aus Ionisation und Blasluft (PDF; 2,2 MB) www.imm-web.de, abgerufen am 8. April 2014"},{"text":"„Der präventive Einsatz eines Ionisationssystems könnte eine erhebliche Verbesserung in der Aufbewahrung und Präsentation solcher Kunst bewirken.“","reference":"Ionen gegen Staub www.restauro.de, abgerufen am 8. April 2014"},{"text":"„Das in die Druckluftpistole integrierte Ionisationssystem verstärkt die Reinigungswirkung der Druckluft durch den Zusatz von Ionen, die statische Aufladungen neutralisieren und dadurch gebundenen Staub lösen.“","reference":"Druckluftpistole mit Ionisierungssystem www.kaiser-fototechnik.de, abgerufen am 12. August 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationssystem","id":"ea94aa0c5a725b"},"0069-006f:48d1c335bba496":{"word":"Ionisationsrauchmelder","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·rauch·mel·der","de-DE":"Io·ni·sa·ti·ons·rauch·mel·der"},"forms":[{"form":"IRM","tags":["Kurzform"]},{"form":"I-Melder","tags":["Kurzform"]},{"form":"Ionisationsrauchmelder","tags":["Nominativ","Singular"]},{"form":"Ionisationsrauchmeldern","tags":["Dativ","Plural"]},{"form":"Ionisationsrauchmelders","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Gerät mit radioaktiven Bauteilen, das Alarm schlägt, wenn es messbar zur Rauchentwicklung im Raum kommt"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Rauchmelder, mit dem Fugenelement -s"],"examples":[{"text":"„Ionisationsrauchmelder (IRM) sind Rauchmelder, in denen radioaktive Stoffe, vorwiegend Americium-241, mit Aktivitäten zwischen 15 bis 40 Kilobecquerel, verwendet werden.“","reference":"Bauartzulassung von Ionisationsrauchmeldern (IRM) www.bfs.de, abgerufen am 8. April 2014"},{"text":"„Der Countdown läuft: Laut Strahlenschutzverordnung müssen veraltete Ionisationsrauchmelder (kurz I-Melder) bis zum 1. Juli 2011 einer Dichtheitsprüfung unterzogen werden.“","reference":"Entsorgung von Ionisationsrauchmeldern www.sicherheit.info, abgerufen am 8. April 2014"},{"text":"„Das Funktionsprinzip der Ionisationsrauchmelder beruht auf der Änderung der Leitfähigkeit von Luft, wenn sie mit bestimmten Partikeln versetzt ist.“","reference":"Was ist ein Ionisationsrauchmelder? www.funk-rauchmelder.net, abgerufen am 8. April 2014"},{"text":"„Schauen wir uns verschiedene Rauch- und Gasmelder genauer an, merken wir sofort, dass sie sich im Innern kaum voneinander unterscheiden – es sei denn, wir legen einen optischen Rauchmelder neben einem sogenannten Ionisationsrauchmelder.“","reference":"Funktionsweise von Brandmelder und Gasmelder www.rauchgasmelder.net, abgerufen am 8. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsrauchmelder","id":"48d1c335bba496"},"0069-006f:2c21d96242d36a":{"word":"Ionisationsspannung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·span·nung","de-DE":"Io·ni·sa·ti·ons·span·nung"},"forms":[{"form":"Ionisationsspannung","tags":["Nominativ","Singular"]},{"form":"Ionisationsspannungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine elektrische Spannung die Ionisation hervorruft"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Spannung, mit dem Fugenelement -s"],"examples":[{"text":"„Zur Ermittlung des Wertes der Ionisationsspannung muss man nun lediglich von dem ermittelten Wert das Kontaktpotential aus 3.3.1 abziehen.“ Physik III -","reference":"Anfangerpraktikum- Bestimmung der Ionisationsspannung(PDF; 79 KB) www.rollke.com, abgerufen am 10. April 2014"},{"text":"„Ausgehend von dem Problem des Auftretens negativer Banden im Stickstoff-nachleuchten in Kaplans Experimenten wird der von Rypdal und Vegard für die Ionisationsspannung des Stickstoffmoleküls vorgeschlagene Wert von etwa 13,3 Volt diskutiert.“","reference":"Über die Ionisationsspannung des Stickstoffmoleküls link.springer.com, abgerufen am 10. April 2014"},{"text":"„Aus dem Stand der Technik ist bekannt, dass das Brenngas-Luft-Verhältnis eines brenngasbetriebenen Brenners mittels Messung der Ionisationsspannung oder des Ionisationsstrom an einer Überwachungselektrode eingestellt werden kann.“","reference":"Verfahren zur Brenngas-Luft-Einstellung für einen brenngasbetriebenen Brenner www.patent-de.com, abgerufen am 10. April 2014"},{"text":"„Die Höhe der Ionisationsspannung steigt mit größerem Elektrodenabstand und wird im Oszilloskopbild als höhere Zündspannungsnadel sichtbar.“","reference":"Zündkerze www.kfz-tech.de, abgerufen am 10. April 2014"},{"text":"„Die Ionisationsspannung liegt bei etwa 5,5 kV und stimmt mit der theoretischen Vorhersage nach Gleichung (4) gut überein.“","reference":"Der Lifter - Ein Flugobjekt mit Ionenantrieb(PDF; 978 KB) phydid.physik.fu-berlin.de, abgerufen am 10. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsspannung","id":"2c21d96242d36a"},"0069-006f:0fcd4d042d045e":{"word":"Ionisierungseffekt","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sie·rungs·ef·fekt","de-DE":"Io·ni·sie·rungs·ef·fekt"},"forms":[{"form":"Ionisierungseffekt","tags":["Nominativ","Singular"]},{"form":"Ionisierungseffekte","tags":["Nominativ","Plural"]},{"form":"Ionisierungseffekten","tags":["Dativ","Plural"]},{"form":"Ionisierungseffektes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"beabsichtigte oder auch unbeabsichtigte Wirkung mit überraschender Auswirkung, die durch Ionisierung auftritt"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisierung und Effekt, mit dem Fugenelement -s"],"examples":[{"text":"„Wie weit die manchmal beobachtete günstige Wirkung einer Allgemeinbestrahlung mit niederer Dosis auf einen Ionisierungseffekt zurückzuführen ist, wäre zu untersuchen.“","reference":"Experimentelle Untersuchungen link.springer.com, abgerufen am 11. April 2014"},{"text":"„Die Förderung der Wolkenbildung durch den Ionisierungseffekt der kosmischen Strahlung, der günstige Bedingungen für die Kondensation von Wasserdampf in der Atmosphäre schafft.“","reference":"Klimavorhersage mit astronomischen Mitteln? www.solidaritaet.com, abgerufen am 11. April 2014"},{"text":"„Es wurde erst ohne weitere Absorption, dann mit steigender Glimmerabsorption bis zum Verschwinden des Ionisierungseffekts gemessen.“","reference":"Ionisation durch H-Strahlen(PDF; 833 KB) www.landesmuseum.at, abgerufen am 11. April 2014"},{"text":"„Außerdem verdampft hierbei ein wenig Material an den Materialoberflächen, was einen zusätzlichen Ionisierungseffekt bringt.“","reference":"Verfahren zum Zünden eines Schweißlichtbogens beim Schutzgasschweißen www.patent-de.com, abgerufen am 11. April 2014"},{"text":"„In diesem Fall führt die Aufspaltung der Wassertropfen dazu, dass das Haar zwar trocknet, einen Teil der Feuchtigkeit aber aufnimmt – nach dem Föhnen glänzt es und fühlt sich weicher an als nach der Behandlung mit einem Haartrockner ohne Ionisierungseffekt.“","reference":"Bürste gegen Struwwelpeter-Haare www.testberichte.de, abgerufen am 11. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisierungseffekt","id":"0fcd4d042d045e"},"0069-006f:93c9cf53f71c3f":{"word":"Ionisationseffekt","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·ef·fekt","de-DE":"Io·ni·sa·ti·ons·ef·fekt"},"forms":[{"form":"Ionisationseffekt","tags":["Nominativ","Singular"]},{"form":"Ionisationseffekte","tags":["Nominativ","Plural"]},{"form":"Ionisationseffekts","tags":["Genitiv","Singular"]},{"form":"Ionisationseffekten","tags":["Dativ","Plural"]},{"form":"Ionisationseffektes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"beabsichtigte oder auch unbeabsichtigte Wirkung mit überraschender Auswirkung, die durch Ionisation auftritt; Molekülanregung"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Effekt, mit dem Fugenelement -s"],"examples":[{"text":"„Treffen Beta-Teilchen auf Materie, treten Ionisationseffekte, Bremsstrahlung, Anregung getroffener Atome und Streuung der Beta-Strahlung selber auf.“","reference":"Wechselwirkung von ionisierender Strahlung mit Materie www.zw-jena.de, abgerufen am 11. April 2014"},{"text":"„ Dabei zeigte sich schon einige Minuten nach Fertigstellung der Präparate ein stets wachsender Ionisationseffekt,der durch mehrere Monate anfangs schnell, später langsam anstieg; wurde das Bleipaket zuvor einer Erhitzung auf über 100° C aus gesetzt, so erfolgte der Anstieg der Ionisationswirkung bedeutend rascher.“","reference":"Untersuchungen über das Eindringen desPoloniums in Metalle(PDF; 587 KB) www.landesmuseum.at, abgerufen am 11. April 2014"},{"text":"„Bei Flammenüberwachungsschaltungen der eingangs erwähnten Art, die den Ionisationseffekt der Flamme ausnutzen, wird meist eine gegenüber dem Bezugspotential das durch die Brennermasse gebildet ist, negative Spannungsversorgung benötigt.“","reference":"Burner monitoring - German Patent DE10159032 www.freepatentsonline.com, abgerufen am 11. April 2014"},{"text":"„Die Ionen, die sich im Bereich hoher Feldstärke befinden werden stark beschleunigt und es finden somit weitere Ionisationseffekte statt.“","reference":"Experimentelle Untersuchungen(PDF; 13,5 MB) www2.uni-frankfurt.de, abgerufen am 11. April 2014"},{"text":"„Bei dem Ionisationseffekt findet eine Streuung des Teilchens mit der Ladung Z.e und der Masse m an einem Elektron mit der Ladung e und der Masse me des Mediums statt.“","reference":"Energiemessung und Teilchenidentifizierung(PDF; 87 KB) wwwa1.kph.uni-mainz.de, abgerufen am 11. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationseffekt","id":"93c9cf53f71c3f"},"0069-006f:bd683381b07ff1":{"word":"Ionisationsvermögen","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·ver·mö·gen","de-DE":"Io·ni·sa·ti·ons·ver·mö·gen"},"forms":[{"form":"Ionisationsvermögen","tags":["Nominativ","Singular"]},{"form":"Ionisationsvermögens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Möglichkeit/Fähigkeit, aus der Hülle eines Atoms Elektronen herauszuschlagen und das Material damit zu ionisieren, zum Beispiel von radioaktiver Strahlung oder von elektrischem Strom oder von Licht"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Vermögen, mit dem Fugenelement -s"],"examples":[{"text":"„Die Al-Messungen von K. Diebner und H. Pose und die Fluormessungen von H. Pose werden bezüglich des Ionisationsvermögens der erzeugten Protonen ausgewertet und die differentielle Ionisation in Abhängigkeit von der Restreichweite untersucht.“","reference":"Das Ionisationsvermögen künstlicher H-Strahlen link.springer.com, abgerufen am 14. April 2014"},{"text":"„Bei Zählrohrspannungen unter 300 V hängt die Zählrate von dem Ionisationsvermögen der einfallenden Strahlung ab.“","reference":"Nachweisgeräte für radioaktive Strahlung (PDF; 573 KB) www.physik-schule.de, abgerufen am 14. April 2014"},{"text":"„Ionisationsvermögen: Parameter der Stossionisation, der angibt, wie viele Atome oder Moleküle ein geladenes Teilchen beim Durchgang durch ein Gas auf einer Flugstrecke von 1 m durch Stossionisation ionisiert.“","reference":"Ionisationsvermögen www.techniklexikon.net, abgerufen am 14. April 2014"},{"text":"„Protonen haben aufgrund ihrer Masse ein viel größeres Ionisationsvermögen als Elektronen vergleichbarer Energie und wir bemerken anhand der besseren Ausbreitungsbedingungen auf den oberen Kurzwellenbändern, daß nach Protonenflares die F-Schicht oft ‚besser reflektiert‘.“","reference":"Protonenereignisse www.darc.de, abgerufen am 14. April 2014"},{"text":"„Das Ionisationsvermögen einer Strahlung ist um so größer, je höher die Masse, denn das Ionisationsvermögen einer Strahlung oder eines Teilchens gibt an, wie stark ein Stoff von ihm ionisiert wird, also die Strahlung Atome durch das Herausschlagen der Elektronen aus der Hülle zu Ionen macht.“","reference":"Vergleich der Strahlungsarten home.arcor.de, abgerufen am 14. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsvermögen","id":"bd683381b07ff1"},"0069-006f:6d6f696b394e07":{"word":"Ionisationsverfahren","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·ver·fah·ren","de-DE":"Io·ni·sa·ti·ons·ver·fah·ren"},"forms":[{"form":"Ionisationsverfahren","tags":["Nominativ","Singular"]},{"form":"Ionisationsverfahrens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"die Art und Weise der Ionisation von etwas; Durchführung"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Verfahren, mit dem Fugenelement -s"],"examples":[{"text":"„Durch die Entwicklung sog. weicher Ionisationsverfahren und entsprechender Massenspektrometer konnte die Arbeitsgruppe um Hoffmann die Konzentrationen einzelner Molekülspezies in den Atmosphärensimulationskammern verfolgen und damit letztlich die Alterung des atmosphärischen Aerosols auf molekularer Basis verstehen.“","reference":"Internationale Forschergruppe weist Alterung von organischen Aerosolen durch OH-Radikale nach www.uni-mainz.de, abgerufen am 14. April 2014"},{"text":"„In der Arbeitsgruppe werden verschiedene Ionisationsverfahren verwendet.“","reference":"Ionisationsverfahren www.zimmermann.chemie.uni-rostock.de, abgerufen am 14. April 2014"},{"text":"„Vor allem Ionisationsverfahren, die bei Atmosphärendruck (engl. Atmospheric Pressure Ionization, API) operieren, stehen im Mittelpunkt der Forschungsaktivitäten.“","reference":"Ausgewählte Forschungsthemen der Chemie an der Bergischen Universität Wuppertal www.chemie.uni-wuppertal.de, abgerufen am 14. April 2014"},{"text":"„Stärker berücksichtigt werden die neuen Ionisationsverfahren und Anwendungen der spektroskopischen und massensprektrometrischen Analysenmethoden.“","reference":"Instrumentelle pharmazeutische Analytik www.deutscher-apotheker-verlag.de, abgerufen am 14. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsverfahren","id":"6d6f696b394e07"},"0069-006f:160e3a159b7989":{"word":"Ionisationsmethode","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·me·tho·de","de-DE":"Io·ni·sa·ti·ons·me·tho·de"},"forms":[{"form":"Ionisationsmethode","tags":["Nominativ","Singular"]},{"form":"Ionisationsmethoden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Art und Weise, wie man etwas ionisiert, um ein bestimmtes Ziel zu erreichen"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Methode, mit dem Fugenelement -s"],"examples":[{"text":"„Für alle diese Anforderungen von Stein und Metall über Gase bis hin zu Biomolekülen hat man in der Massenspektrometrie passende Ionisationsmethoden zur Hand.“","reference":"Ionisationsmethoden in der Massenspektroskopie www.dgms-online.de, abgerufen am 14. April 2014"},{"text":"„Nicht jede Verbindung ist für jede Ionisationsmethode geeignet.“","reference":"Auswahl der Ionisations-Methode www.orgchem.uni-essen.de, abgerufen am 14. April 2014"},{"text":"„Nicht jeder Analyt ist für jede Ionisationsmethode geeignet. Ferner ist nicht jede Ionisationsmethode an allen Geräten verfügbar.“","reference":"MS-Ionisationsmethoden www.uni-due.de, abgerufen am 14. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsmethode","id":"160e3a159b7989"},"0069-006f:845214f3202ab7":{"word":"Ionisationsmodul","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·mo·dul","de-DE":"Io·ni·sa·ti·ons·mo·dul"},"forms":[{"form":"Ionisationsmodul","tags":["Nominativ","Singular"]},{"form":"Ionisationsmodule","tags":["Nominativ","Plural"]},{"form":"Ionisationsmoduls","tags":["Genitiv","Singular"]},{"form":"Ionisationsmodulen","tags":["Dativ","Plural"]}],"senses":[{"definition":"eine technische Einheit die etwas ionisiert und Bauteil in einem größeren System ist"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Modul, mit dem Fugenelement -s"],"examples":[{"text":"„Ebenso lässt sich durch den Einbau eines Ionisationsmoduls mit Ionisationsröhre die Luftqualität verbessern und Schadstoffe abbauen.“","reference":"Passivhaus www.energieberatung-nofz.de, abgerufen am 14. April 2014"},{"text":"„Hauptbestandteil der Anlage ist ein Ionisationsmodul mit bis zu 5 Röhren, wie es in der Testanlage installiert ist.“","reference":"Einsatz eines alternativen Abluftreinigungsverfahrens(PDF; 2,8 MB) www.fachdokumente.lubw.baden-wuerttemberg.de, abgerufen am 14. April 2014"},{"text":"„Daher wird vorteilhaft das Ionisationsmodul fest mit dem Filter verbunden, so daß das Ionisationsmodul mit dem verbrauchten Filter ausgetauscht wird.“","reference":"Apparat zur Entstaubung, Deodorierung und Sterilisierung von Luft www.freepatentsonline.com, abgerufen am 15. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsmodul","id":"845214f3202ab7"},"0069-006f:01e84c603e812c":{"word":"Ionisationspotential","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·po·ten·ti·al","de-DE":"Io·ni·sa·ti·ons·po·ten·ti·al"},"forms":[{"form":"Ionisationspotential","tags":["Nominativ","Singular"]},{"form":"Ionisationspotentiale","tags":["Nominativ","Plural"]},{"form":"Ionisationspotentials","tags":["Genitiv","Singular"]},{"form":"Ionisationspotentialen","tags":["Dativ","Plural"]}],"senses":[{"definition":"physikalische Größe zur Beschreibung eines Feldes/Verbindung oder von Energie, die etwas ionisiert"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Potential, mit dem Fugenelement -s; neue Schreibweise: Ionisationspotenzial"],"examples":[{"text":"Das Ionisationspotential von Benzol beträgt 9,2 eV.","reference":"Massenspektrometer - Die Ionenquelle - Chemische Ionisation www.chemgapedia.de, abgerufen am 16. April 2014"},{"text":"„Die Resultate dieser Messungen, darunter auch das erstmals gemessene Ionisationspotential, wurden jetzt in der angesehenen Fachzeitschrift \"Nature\" veröffentlicht.“","reference":"S. Rothe misst erstmals das Ionisationspotential des seltenen radioaktiven Elements Astat www.larissa.physik.uni-mainz.de, abgerufen am 16. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationspotential","id":"01e84c603e812c"},"0069-006f:10b837289ae102":{"word":"Ionisationspotenzial","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·po·ten·zi·al","de-DE":"Io·ni·sa·ti·ons·po·ten·zi·al"},"forms":[{"form":"Ionisationspotential","tags":["alternative"]},{"form":"Ionisationspotenzial","tags":["Nominativ","Singular"]},{"form":"Ionisationspotenziale","tags":["Nominativ","Plural"]},{"form":"Ionisationspotenzials","tags":["Genitiv","Singular"]},{"form":"Ionisationspotenzialen","tags":["Dativ","Plural"]},{"form":"Maßeinheit: eV","tags":["symbol"]}],"senses":[{"definition":"Bindungsenergie, die angibt, welche Energie nötig ist, um ein Elektron aus der äußeren Schale des Atoms zu entfernen"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Potenzial, mit dem Fugenelement -s"],"examples":[{"text":"Das Ionisationspotenzial von Ethanol beträgt 10,6 eV.","reference":"Protonenaffinität und Ionisationspotenzial einiger Analyten - Ionisationspotenzial in eV www.chemgapedia.de, abgerufen am 17. April 2014"},{"text":"„Das Ionisationspotenzial beschreibt die Energie, die aufgewendet werden muss, um ein Elektron aus dem Molekül zu entfernen und damit ein positives Molekülion zu bilden.“","reference":"Ionisationspotenzial www.chemgapedia.de, abgerufen am 16. April 2014"},{"text":"„Dem Mainzer Physiker Sebastian Rothe ist es nun anhand von künstlich erzeugtem Astat erstmals gelungen, die fundamentale Größe des Ionisationspotenzials zu ermitteln und damit eine der wichtigsten Eigenschaften des seltenen Elements zu bestimmen.“","reference":"Ionisationspotenzial des radioaktiven Elements Astat bestimmt www.phmi.uni-mainz.de, abgerufen am 16. April 2014"},{"text":"„Wegen des niedrigen Ionisationspotenzials der L̈oschgasionen sind diese nicht mehr in der Lage, am Mantel Sekundärelektronen auszulösen, und der Entladungsprozess erlischt.“","reference":"Gasdetektoren und Statistik(PDF; 222 KB) www.physik.rwth-aachen.de, abgerufen am 16. April 2014"},{"text":"„Es gibt nun zwei Energiewerte, die bei Untersuchung eines Gases von Interesse sind: Erstens das Ionisationspotential des Gases, d. i. die zur Erzeugung eines Ionenpaares notwendige Energie, und zweitens der mittlere Energieaufwand pro erzeugtem Ionenpaar, d. i. die von einer a-Partikel durchschnittlich zur Erzeugung eines Ionenpaares aufgewendete Energie, die infolge des darin miteingerechneten Energieaufwandes für Anregung und Dissoziation größer ist als die allein zur Ionisation notwendige Energie.“","reference":"Ionisationsmessungen in Helium und Neon(PDF; 820 KB) www.landesmuseum.at, abgerufen am 16. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationspotenzial","id":"10b837289ae102"},"0069-006f:0be586d3448ac8":{"word":"Ionisationsmessung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·mes·sung","de-DE":"Io·ni·sa·ti·ons·mes·sung"},"forms":[{"form":"Ionisationsmessung","tags":["Nominativ","Singular"]},{"form":"Ionisationsmessungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Verfahren zur Bestimmung der Geschwindigkeit und Intensität geladener Teilchen; Detektion"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Messung, mit dem Fugenelement -s"],"examples":[{"text":"„Man wird also, wenn man Ionisationsmessungen ausführt, nicht die ganze Energie der Partikeln in Form von potentieller Energie der erzeugten Ionen wiederfinden, da ein Teil der Energie auf Anregung und Dissoziation verbraucht wird, der bei dieser Messung nicht erfaßt werden kann.“","reference":"Ionisationsmessungen in Helium und Neon(PDF; 820 KB) www.landesmuseum.at, abgerufen am 18. April 2014"},{"text":"„Die elektronische Steuerung verwendet den Glühzünder zur Flammendetektion mithilfe der Ionisationsmessung.“","reference":"Edelstahl Gas-Vorratswasser-heizer - Brennwerttechnologie arbeitend(PDF; 3,7 MB) www.aosmithinternational.com, abgerufen am 18. April 2014"},{"text":"„Zum Betrieb der Ionisationsmessung und zur elektrischen Zündung des Brennstoff werden im Gerät sehr hohe Spannungen erzeugt, welche lebensgefährlich sein können.“","reference":"Showtechnik - Pyrotechnik(PDF; 1,6 MB) www.firework.de, abgerufen am 18. April 2014"},{"text":"„Zu den Brandfolgeerscheinungen zählen: Temperatur (z. B. Überschreiten bestimmter Temperaturerhöhungen pro Zeiteinheit, vorgegebener Temperaturgrenzwert, Volumenänderung infolge Temperatureinwirkung), Brandrauch (Messen der abnormen Lichttrübung oder -brechung), unsichtbare Brandgase (feststellbar z. B. durch Ionisationsmessung und Gasanalyse) und Flammen (Messen der Wellenlänge des Flammenlichtes oder des Flackereffektes bei der Pulsation der frei brennenden Flammen).“","reference":"Brandmeldeanlage www.juramagazin.de, abgerufen am 18. April 2014"},{"text":"„Er führte 1910 und 1911 mit Wulfschen Elektrometern Ionisationsmessungen an Land und auf dem Meer durch.“","reference":"Victor Hess und die Entdeckung der kosmischen Strahlung www.weltderphysik.de, abgerufen am 18. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsmessung","id":"0be586d3448ac8"},"0069-006f:43637ff51315d9":{"word":"Ionisationsenergie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·en·er·gie","de-DE":"Io·ni·sa·ti·ons·en·er·gie"},"forms":[{"form":"Ei","tags":["symbol"]},{"form":"IE","tags":["Kurzform"]},{"form":"Ionisationsenergie","tags":["Nominativ","Singular"]},{"form":"Ionisationsenergien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Energie, die für die Ionisation mindestens aufgewendet werden muss"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Energie, mit dem Fugenelement -s"],"examples":[{"text":"„Zahlenwerte für die Ionisationsenergie für praktisch alle Elemente finden sich über die Links, die vom Modul Periodensystem ausgehen.“","reference":"Ionisationsenergien und Elektronegativitäten einiger Elemente www.tf.uni-kiel.de, abgerufen am 18. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsenergie","id":"43637ff51315d9"},"0069-006f:e2cb8d97470cd2":{"word":"Ionisationszeit","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·zeit","de-DE":"Io·ni·sa·ti·ons·zeit"},"forms":[{"form":"Ionisationszeit","tags":["Nominativ","Singular"]},{"form":"Ionisationszeiten","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine bestimmtes Zeitfenster, in dem gezielt Ionisation stattfindet"},{"definition":"eine unbestimmtes Zeitfenster, in dem Ionisation wirkt"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Zeit, mit dem Fugenelement -s"],"examples":[{"text":"„Die zwei Hauptfaktoren, die die Ionenanzahl beeinflussen, sind die Ionisationszeit und die Amplitude der RF Spannung während der Ionisation.“","reference":"Einführung in die Massenspektrometrie www.ivv.fraunhofer.de, abgerufen am 18. April 2014"},{"text":"„Um die Ionisationszeit zu optimieren muss sowohl auf die emittierte Wellenlänge als auch auf die optische Leistung geachtet werden.“","reference":"Aufbau eines Ionisationslasers(PDF; 26,3 MB) xqp.physik.uni-muenchen.de, abgerufen am 18. April 2014"},{"text":"„Misst man den Winkel der Elektronenflugrichtung, so kann man den Winkel des elektrischen Feldes zur Ionisationszeit berechnen, und dieser Winkel dreht sich während eines optischen Zyklus um 360°.“","reference":"Attosekundengenaue Tunnelzeitmessung www.ulp.ethz.ch, abgerufen am 18. April 2014"},{"text":"„Für niedrige Konzentrationen, wie z.B. die Basislinie oder kleine GC Peaks, wird die maximale Ionisationszeit für die eigentliche ausgewählt.“","reference":"Ionenfallen-Massenspektrometer www.chemie.de, abgerufen am 18. April 2014"},{"text":"„Vorher sichtbare Reflektionen werden durch die Ionisationszeit verzögert, und stellen den Vorgang dar, während dem der Fehler anfängt zu zünden.“","reference":"Kabelfehlerortung an Energiekabeln(PDF; 599 KB) www.sebakmt.com, abgerufen am 18. April 2014"},{"text":"„ Die Dauer der Ionisation (hierin als \"Ionisationszeit\" bezeichnet) ist ein wichtiger Faktor, der den Wirkungsgrad des Motors beeinflusst, und es ist normalerweise wünschenswert, dass die Ionisationszeit jeder Zündkerze im Wesentlichen gleich der Ionisationszeit jeder anderen Zündkerze des Motors, und außerdem gleich einer nominellen Ionisationszeit ist.“","reference":"Ionisationskontrolle für Zündsysteme www.patent-de.com, abgerufen am 18. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationszeit","id":"e2cb8d97470cd2"},"0069-006f:61281d721c6f81":{"word":"Ionisationsmessröhre","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·mess·röh·re","de-DE":"Io·ni·sa·ti·ons·mess·röh·re"},"forms":[{"form":"FIG","tags":["Kurzform"]},{"form":"Ionisationsmeßröhre","tags":["obsolete"]},{"form":"Ionisationsmessröhren","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine Elektronenröhre zur Vakuummessung"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Messröhre, mit dem Fugenelement -s"],"examples":[{"text":"Die Ionisationsmessröhre wurde durch Werner von Siemens ca. 1905 entwickelt und war eine reine Vakuummessröhre.","reference":""},{"text":"„Schalten Sie die Ionisationsmessr̈ohre ab und belüften Sie den Kessel.“","reference":"Praktikum f̈ur Fortgeschrittene - Versuch Vakuumtechnik(PDF; 156 KB) www.uni-saarland.de, abgerufen am 25. April 2014"},{"text":"„In einer Ionisationsmessröhre wird ein konstanter Strom von Elektronen aus einer Glühkathode emittiert und beschleunigt.“","reference":"Beugung langsamer Elektronen (LEED)(PDF; 120 KB) www.fp.fkp.uni-erlangen.de, abgerufen am 25. April 2014"},{"text":"„Um nach einem Adsorptionsexperiment die genaue Menge des angebotenen Gases bestimmen zu können, wurde während der Experimente der von der Ionisationsmessröhre angezeigte Druck aufgezeichnet.“","reference":"Dr.-Arbeit Dipl.-Phys. Mathias Sinther an der Ruprecht-Karls-Universität(PDF; 6,5 MB) archiv.ub.uni-heidelberg.de, abgerufen am 25. April 2014"},{"text":"„Der Druck im Rezipienten wird mit einer Bayard-Alpert-Ionisationsmessröhre gemessen (Typ Varian UHV-24, Steuerung durch eine Eigenkonstruktion des Instituts für Physikalische Chemie).“","reference":"Messverfahren - Röntgen-Photoelektronen-Spektroskopie (XPS)(PDF; 417KB) repositorium.uni-muenster.de, abgerufen am 25. April 2014"},{"text":"„ Die Gaslinie verf̈ugt darüber hinaus über ein MKS-Barathron 121AA (PDR-D-2 Controller) sowie eine Ionisationsmessröhre IMR325(IMG 300 Controller, Pfeiffer Vacuum).“","reference":"Dr.-Arbeit von A. Martin R̈ottgen an der TU München(PDF; 1,9 MB) mediatum.ub.tum.de, abgerufen am 25. April 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsmessröhre","id":"61281d721c6f81"},"0069-006f:0daa860c5f2964":{"word":"Ionisationsvorgang","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·sa·ti·ons·vor·gang","de-DE":"Io·ni·sa·ti·ons·vor·gang"},"forms":[{"form":"Ionisationsvorgang","tags":["Nominativ","Singular"]},{"form":"Ionisationsvorgange","tags":["Dativ","Singular"]},{"form":"Ionisationsvorgangs","tags":["Genitiv","Singular"]},{"form":"Ionisationsvorgänge","tags":["Nominativ","Plural"]},{"form":"Ionisationsvorganges","tags":["Genitiv","Singular"]},{"form":"Ionisationsvorgängen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Ablauf, ein Geschehen, bei dem Ionisation stattfindet"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Ionisation und Vorgang, mit dem Fugenelement -s"],"examples":[{"text":"„In dem nachfolgenden Ionisationsvorgang werden von den Atomen jeweils ein oder mehrere Elektronen abgetrennt.“","reference":"Plasma - Definition www.unibw.de, abgerufen am 15. Mai 2014"},{"text":"„Röntgenstrahlung hat folgende Eigenschaften: Sie ist wie Alpha-, Beta-, Gamma- und Neutronenstrahlung ionisierend, da sie Ionisationsvorgänge (Herauslösen von Elektronen) an Atomen und Molekülen in von ihr durchdrungener Materie auslösen kann.“","reference":"Röntgenstrahlung www.stmuv.bayern.de, abgerufen am 15. Mai 2014"},{"text":"„Ionisiertes Wasser, also reduziertes Wasser, das durch einen Ionisationsvorgang von seinen sauren Bestandteilen getrennt wurde, hat viele positive Eigenschaften.“","reference":"Ionisiertes Wasser - die Hintergründe www.hilfreich.de, abgerufen am 15. Mai 2014"},{"text":"„Der Prozess der Kernumwandlung wird in der Regel als Kernzerfall und die abgegebene Strahlung - wegen ihrer Eigenschaft, bei der Durchdringung von Stoffen an Atomen und Molekülen Ionisationsvorgänge auszulösen - als ionisierende Strahlung bezeichnet.“","reference":"Was ist ionisierende Strahlung? www.bfs.de, abgerufen am 15. Mai 2014"},{"text":"„In der theoretischen Betrachtung der Ionisationsvorgänge reicht es deshalb oftmals aus, nur die Einfachionisation einzubeziehen.“","reference":"Praktikum an einer EBIS (PDF; 12,9 MB) praktikum.phy.tu-dresden.de, abgerufen am 15. Mai 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionisationsvorgang","id":"0daa860c5f2964"},"0069-006f:5514c695b4a442":{"word":"Ionisch","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·nisch","de-DE":"Io·nisch"},"forms":[{"form":"das Ionische","tags":["Nominativ","Singular"]},{"form":"(das) Ionisch","tags":["Nominativ","Singular"]},{"form":"(dem) Ionisch","tags":["Dativ","Singular"]},{"form":"(des) Ionisch","tags":["Genitiv","Singular"]},{"form":"dem Ionischen","tags":["Dativ","Singular"]},{"form":"des Ionischen","tags":["Genitiv","Singular"]},{"form":"(des) Ionischs","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Dialekt des Altgriechischen, der an der südlichen Westküste Vorderasiens gesprochen wurde"}],"synonyms":["Ionen..."],"origins":[],"examples":[{"text":"Ionisch ist eng mit dem Attischenen verwandt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ionisch","id":"5514c695b4a442"},"0069-006f:5b49909307102d":{"word":"Ionenantrieb","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·nen·an·trieb","de-DE":"Io·nen·an·trieb"},"forms":[{"form":"Ionenantrieb","tags":["Nominativ","Singular"]},{"form":"Ionenantriebe","tags":["Nominativ","Plural"]},{"form":"Ionenantriebs","tags":["Genitiv","Singular"]},{"form":"Ionenantrieben","tags":["Dativ","Plural"]},{"form":"Ionenantriebes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Antrieb, bei dem der Ausstoß eines Ionenstrahls für die Fortbewegung genutzt wird"}],"synonyms":["Ionentriebwerk"],"origins":["Determinativkompositum aus Ion, Fugenelement -en und Antrieb"],"examples":[{"text":"„In den letzten Jahren hat sich das Prinzip des Ionenantriebes mit Xenon als Arbeitsmedium als zukunftsträchtig erwiesen.“","reference":"Ionentriebwerke: Der Ritt auf geladenen Teilchen. Abgerufen am 14. Dezember 2019."},{"text":"„Klassische Raketenantriebe sind chemisch und basieren auf der Verbrennung riesiger Mengen an Treibstoff. Die Alternative sind elektrische Antriebe, zu denen auch Ionenantriebe gehören.“","reference":"Karin Krichmayr: Wie der Elektroantrieb die Raumfahrt revolutioniert. In: Der Standard digital. 27. September 2019 (URL, abgerufen am 9. Februar 2026) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ionenantrieb","id":"5b49909307102d"},"0069-006f:ab5e9a2336be33":{"word":"Ionentriebwerk","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Io·nen·trieb·werk","de-DE":"Io·nen·trieb·werk"},"forms":[{"form":"Ionentriebwerk","tags":["Nominativ","Singular"]},{"form":"Ionentriebwerke","tags":["Nominativ","Plural"]},{"form":"Ionentriebwerks","tags":["Genitiv","Singular"]},{"form":"Ionentriebwerken","tags":["Dativ","Plural"]},{"form":"Ionentriebwerkes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Antrieb, bei dem der Ausstoß eines Ionenstrahls für die Fortbewegung genutzt wird"}],"synonyms":["Ionenantrieb"],"origins":["Determinativkompositum aus Ion, Fugenelement -en und Triebwerk"],"examples":[{"text":"„Sie hat nämlich kein chemisches Triebwerk an Bord, sondern ein Ionentriebwerk, das nur einen Schub von 70 Millinewton erreicht.“","reference":"Der lange Weg zum Erdtrabanten. Abgerufen am 18. November 2023."},{"text":"„Ionentriebwerke beschleunigen elektrisch geladene Partikel und stoßen sie entgegen der Flugrichtung aus.“","reference":"Neues Ionentriebwerk entwickelt. Abgerufen am 14. Dezember 2019."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ionentriebwerk","id":"ab5e9a2336be33"},"0069-006f:486fac7007d58a":{"word":"Ionenstrahl","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·nen·strahl","de-DE":"Io·nen·strahl"},"forms":[{"form":"Ionenstrahl","tags":["Nominativ","Singular"]},{"form":"Ionenstrahle","tags":["Dativ","Singular"]},{"form":"Ionenstrahls","tags":["Genitiv","Singular"]},{"form":"Ionenstrahlen","tags":["Nominativ","Plural"]},{"form":"Ionenstrahles","tags":["Genitiv","Singular"]}],"senses":[{"definition":"mit einer Ionenquelle künstlich erzeugte Kette von schnell aufeinanderfolgenden elektrisch geladenen Teilchen (Ionen)"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Ion und Strahl mit dem Fugenelement -en"],"examples":[{"text":"In elektrischen und magnetischen Gleich- und Wechselspannungsfeldern werden die Ionenstrahlen dann transportiert und auch in ihren Eigenschaften beeinflusst.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionenstrahl","id":"486fac7007d58a"},"0069-006f:dd66ddb9aaf09e":{"word":"ionisierend","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"io·ni·sie·rend","de-DE":"io·ni·sie·rend"},"forms":[{"form":"ionisierend","tags":["Positiv"]},{"form":"ionisierende","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ionisierendem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ionisierenden","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ionisierender","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"ionisierendes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist ionisierend","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ionisierend","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ionisierend","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind ionisierend","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"ein oder mehrere Elektronen zu einem Atom oder Molekül hinzufügend oder entfernend und damit den elektrischen Ladungszustand verändernd"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die ionisierende Wirkung der radioaktiven Strahlung wird zur Messung ihrer Intensität in Strahlungsmeßgeräten (Elektrometer, Ionisationskammer und Geiger-Müller- Zählrohr) ausgenutzt.“","reference":"Karl A. Hofmann: Anorganische Chemie. 21. Auflage. Springer, 1973, Seite 495 (Zitiert nach Google Books) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ionisierend","id":"dd66ddb9aaf09e"},"0069-006f:ea4c12f2628a86":{"word":"Ionicus a minore","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·cus a mi·no·re","de-DE":"Io·ni·cus a mi·no·re"},"forms":[{"form":"Ionici a minore","tags":["Nominativ","Plural"]},{"form":"Ionicus a minore","tags":["Nominativ","Singular"]}],"senses":[{"definition":"viersilbiger Versfuß, bei dem auf zwei kurze Silben zwei lange folgen (υ υ – –)"}],"synonyms":[],"origins":[],"examples":[{"text":"„Molossus (lang lang lang – – –) kann die Kontraktion eines Choriambus, eines Ionicus a minore oder a maiore sein […].“","reference":"Friedrich Crusius: Römische Metrik. Eine Einführung. Neu bearbeitet von Hans Rubenbauer. 8. Auflage. Max Hueber Verlag, München 1967 , Seite 34."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionicus a minore","id":"ea4c12f2628a86"},"0069-006f:aff59bdda94159":{"word":"Ionicus a maiore","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·cus a maio·re","de-DE":"Io·ni·cus a maio·re"},"forms":[{"form":"Ionici a maiore","tags":["Nominativ","Plural"]},{"form":"Ionicus a maiore","tags":["Nominativ","Singular"]}],"senses":[{"definition":"viersilbiger Versfuß, bei dem auf zwei lange Silben zwei kurze folgen (– – υ υ)"}],"synonyms":[],"origins":[],"examples":[{"text":"„Molossus (lang lang lang – – –) kann die Kontraktion eines Choriambus, eines Ionicus a minore oder a maiore sein […].“","reference":"Friedrich Crusius: Römische Metrik. Eine Einführung. Neu bearbeitet von Hans Rubenbauer. 8. Auflage. Max Hueber Verlag, München 1967 , Seite 34."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionicus a maiore","id":"aff59bdda94159"},"0069-006f:d10fc344c747c6":{"word":"Ionenbindung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·nen·bin·dung","de-DE":"Io·nen·bin·dung"},"forms":[{"form":"Ionenbindung","tags":["Nominativ","Singular"]},{"form":"Ionenbindungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"elektrostatische Anziehung positiv und negativ geladener Ionen, besonders bei Ionengittern"}],"synonyms":["elektrovalente Bindung","heteropolare Bindung","ionische Bindung"],"origins":["Determinativkompositum, zusammengesetzt aus dem Substantiv Ion, Fugenelement -en und dem Substantiv Bindung"],"examples":[{"text":"„Kochsalz setzt sich somit aus Natrium- und Chlorid-Ionen zusammen, die eine Ionenbindung eingehen.“","reference":"Patrick Messner: Ionenbindung. In: DocCheck Flexikon. Abgerufen am 23. Juli 2019."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ionenbindung","id":"d10fc344c747c6"},"0069-006f:009464ccd9c1c0":{"word":"Iodquelle","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Iod·quel·le","de-DE":"Iod·quel·le"},"forms":[{"form":"Iodquelle","tags":["Nominativ","Singular"]},{"form":"Jodquelle","tags":["variant"]},{"form":"Iodquellen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Ursprung (Quelle) für das chemische Element Iod"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus Iod und Quelle"],"examples":[{"text":"„Eine neuere Synthese nutzt die Kombination aus Iod und Kaliumiodid als Iodquelle und Natriumhypochlorit als Oxidationsmittel.“","reference":"Wikipedia-Artikel „1,3-Diiod-5,5-dimethylhydantoin“"},{"text":"„In zahlreichen neueren Studien an verschiedenen Tierspezies hat sich Erythrosin als Iodquelle unterschiedlicher Ausnutzbarkeit erwiesen.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 8. Mai 2020."},{"text":"„Aus der vorhergehenden Analyse […] geht hervor, dass nicht nur die Thassiloquelle alle übrigen in ihrem Iodgehalte bei Weitem übertrifft, sondern dass selbst das zum Badegebrauche verwendete gemischte Iodwasser mehr Iod enthält, als die stärkste Iodquelle zu Heilbronn.“ (1860)","reference":"Fehlender Parameter (Hilfe) Abgerufen am 8. Mai 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Iodquelle","id":"009464ccd9c1c0"},"0069-006f:f5a1e05991d520":{"word":"iodidhaltig","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"iod·id·hal·tig","de-DE":"iod·id·hal·tig"},"forms":[{"form":"iodidhaltig","tags":["Positiv"]},{"form":"iodidhaltige","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"iodidhaltigem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"iodidhaltigen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"iodidhaltiger","tags":["Komparativ"]},{"form":"iodidhaltiges","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"iodidhaltigere","tags":["Komparativ","Nominativ","strong","Singular","feminine"]},{"form":"iodidhaltigste","tags":["Superlativ","Nominativ","strong","Singular","feminine"]},{"form":"iodidhaltigerem","tags":["Komparativ","Dativ","strong","Singular","masculine"]},{"form":"iodidhaltigeren","tags":["Komparativ","Genitiv","strong","Singular","masculine"]},{"form":"iodidhaltigerer","tags":["Komparativ","Nominativ","strong","Singular","masculine"]},{"form":"iodidhaltigeres","tags":["Komparativ","Nominativ","strong","Singular","neuter"]},{"form":"iodidhaltigstem","tags":["Superlativ","Dativ","strong","Singular","masculine"]},{"form":"iodidhaltigsten","tags":["Superlativ","Genitiv","strong","Singular","masculine"]},{"form":"iodidhaltigster","tags":["Superlativ","Nominativ","strong","Singular","masculine"]},{"form":"iodidhaltigstes","tags":["Superlativ","Nominativ","strong","Singular","neuter"]},{"form":"am iodidhaltigsten","tags":["Superlativ"]},{"form":"er ist iodidhaltig","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist iodidhaltig","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist iodidhaltig","tags":["Positiv","predicative","Singular","feminine"]},{"form":"er ist iodidhaltiger","tags":["Komparativ","predicative","Singular","masculine"]},{"form":"es ist iodidhaltiger","tags":["Komparativ","predicative","Singular","neuter"]},{"form":"sie sind iodidhaltig","tags":["Positiv","predicative","Plural"]},{"form":"sie ist iodidhaltiger","tags":["Komparativ","predicative","Singular","feminine"]},{"form":"sie sind iodidhaltiger","tags":["Komparativ","predicative","Plural"]},{"form":"er ist am iodidhaltigsten","tags":["Superlativ","predicative","Singular","masculine"]},{"form":"es ist am iodidhaltigsten","tags":["Superlativ","predicative","Singular","neuter"]},{"form":"sie ist am iodidhaltigsten","tags":["Superlativ","predicative","Singular","feminine"]},{"form":"sie sind am iodidhaltigsten","tags":["Superlativ","predicative","Plural"]}],"senses":[{"definition":"Iodid (= eine Verbindung von Iod mit einem Metall, beispielsweise Silberjodid, Kupferiodid) enthaltend"}],"synonyms":[],"origins":["Kompositum (Zusammensetzung) aus dem Substantiv Iodid mit dem Suffix -haltig"],"examples":[{"text":"„Dabei handelt es sich um eine direkte Titration einer chlorid-, bromid- oder iodidhaltigen Lösung mit einer Silbernitrat-Maßlösung.“","reference":"Titration nach Fajans. chemie.de, LUMITOS AG, Berlin, Deutschland, abgerufen am 30. April 2021."},{"text":"„Zwischen der Extinktion bei 350 nm und der Gesamtiodkonzentration von iodidhaltigen, wäßrigen Lösungen besteht unabhängig vom pH-Wert ein weitgehend linearer Zusammenhang, der zur quantitativen Bestimmung von Iod und Iod-freisetzenden Oxidationsmitteln herangezogen werden kann.“","reference":"W. Gottardi: Photometrische Bestimmung von Iod und Iod-freisetzenden Oxidationsmitteln. link.springer.com, Springer Nature Switzerland AG , Cham, Switzerland, 1982, abgerufen am 30. April 2021."},{"text":"„Im Gegensatz zur Volumetrie ist eine Titerbestimmung in der Coulometrie nicht erforderlich. Da das Iod aus dem iodidhaltigen Reagenz elektrolytisch erzeugt wird, handelt es sich bei der coulometrischen Karl-Fischer-Titration um eine absolute Methode.“","reference":"Fehlender Parameter (Hilfe) Michael Margreth: 2016, abgerufen am 30. April 2021 (Deutsch)."},{"text":"„Der iodidhaltige Nitro‐Katalysator wurde von Wissenschaftlern der Firma […] hergestellt und in einer Reihe anspruchsvoller RCM‐ und CM‐Reaktionen, unter anderem auch in “grünen” Lösungsmitteln getestet (Schema 22).“","reference":"Dr. Anna Kajetanowicz, Prof. Dr. Karol Grela: Durch Nitro‐ und andere elektronenziehende Gruppen aktivierte Ruthenium‐Katalysatoren für die Olefinmetathese. onlinelibrary.wiley.com, John Wiley & Sons, Inc., Hoboken, New Jersey, USA, 18. August 2020, abgerufen am 30. April 2021."},{"text":"„Als Gründe für die relativ hohen Iodidgehalte der Milchen werden zum einen iodidhaltige Mineralstoffgemische im Tierfutter (5 – 10 mg I- / kg), zum anderen die Reinigung von Produktions - und Melkanlagen sowie zur Zitzendesinfektion verwendete Iodophore angesehen.“","reference":"Julia Kairies: Der Anteil verschiedener Lebensmittel an der alimentären Iodversorgung in Deutschland. Klinik für Innere Medizin der Universität Rostock, Abteilung für Endokrinologie, Rostok, Deutschland, 28. März 2008, abgerufen am 30. April 2021 (Deutsch)."},{"text":"„Personen mit Milchallergie oder Lactoseintoleranz nehmen ebenfalls unzureichende Iodmengen über die Nahrung auf. Diese Gruppen sollten unbedingt mit iodidhaltigen Präparaten ihren Iodbedarf für die Schilddrüsenhormonsynthese decken, da sonst das Risiko für Kropfbildung und daraus resultierende Folgeerkrankungen steigt.“","reference":"Josef Köhrle: Iod – Immer noch unterversorgt. pharmazeutische-zeitung.de, Pharmazeutische Zeitung online, Avoxa – Mediengruppe Deutscher Apotheker GmbH, Apothekerhaus Eschborn, Eschborn, Deutschland, 2. Januar 2006, abgerufen am 30. April 2021."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"iodidhaltig","id":"f5a1e05991d520"},"0069-006f:44d5d7d49c8360":{"word":"Ionier","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Io·ni·er","de-DE":"Io·ni·er"},"forms":[{"form":"Ioner","tags":["variant"]},{"form":"Ionier","tags":["Nominativ","Singular"]},{"form":"Ioniern","tags":["Dativ","Plural"]},{"form":"Ioniers","tags":["Genitiv","Singular"]},{"form":"Ionierin","tags":["feminine"]}],"senses":[{"definition":"Angehöriger eines antiken Stammes, der in Griechenland und Kleinasien siedelte"}],"synonyms":[],"origins":[],"examples":[{"text":"„Tatsächlich sahen sich die Griechen überwiegend als Abkömmlinge von Invasoren, den von den Herakleiden angeführten Dorern und Äölern, welche die einheimischen Pelasger, Achäer und Ionier verdrängt hätten.“","reference":"Michael Sommer: Ein Ende mit Schrecken. In: DAMALS. Das Magazin für Geschichte. Nummer 12, 2018, ISSN 0011-5908, Seite 44 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionier","id":"44d5d7d49c8360"},"0069-006f:c0efd3e8ebbf68":{"word":"Iodatom","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Iod·atom","de-DE":"Iod·atom"},"forms":[{"form":"Iodatom","tags":["Nominativ","Singular"]},{"form":"Jodatom","tags":["variant"]},{"form":"Iodatome","tags":["Nominativ","Plural"]},{"form":"Iodatoms","tags":["Genitiv","Singular"]},{"form":"Iodatomen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Atom des chemischen Elements Iod"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Iod und Atom"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Iodatom","id":"c0efd3e8ebbf68"},"0069-006f:338305c50e45d4":{"word":"Ionien","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Io·ni·en","de-DE":"Io·ni·en"},"forms":[{"form":"Ioniens","tags":["Genitiv","Singular"]},{"form":"des Ionien","tags":["Genitiv","Singular"]},{"form":"des Ioniens","tags":["Genitiv","Singular"]},{"form":"(das) Ionien","tags":["Nominativ","Singular"]},{"form":"(dem) Ionien","tags":["Dativ","Singular"]}],"senses":[{"definition":"historische Landschaft und Siedlungsgebiet der Ionier an der Westküste der heutigen Türkei"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionien","id":"338305c50e45d4"},"0069-006f:1aedbe22d8e309":{"word":"Ionierin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Io·ni·e·rin","de-DE":"Io·ni·e·rin"},"forms":[{"form":"Ionier","tags":["masculine"]},{"form":"Ionierin","tags":["Nominativ","Singular"]},{"form":"Ionierinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weiblicher Angehöriger eines antiken Stammes, der in Griechenland und Kleinasien siedelte"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Ionier mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ionierin","id":"1aedbe22d8e309"},"0069-006f:b29661f842c60d":{"word":"Iowa City","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Iowa City","de-DE":"Iowa City"},"forms":[{"form":"Iowa Citys","tags":["Genitiv","Singular"]},{"form":"des Iowa City","tags":["Genitiv","Singular"]},{"form":"des Iowa Citys","tags":["Genitiv","Singular"]},{"form":"(das) Iowa City","tags":["Nominativ","Singular"]},{"form":"(dem) Iowa City","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt im US-Bundesstaat Iowa"}],"synonyms":[],"origins":[],"examples":[{"text":"„In Iowa City gabelte Kevin, unser Tänzer mit diatrophischer Dysplasie, eine Junggesellin auf.“","reference":"Chuck Palahniuk: Mister Elegant. In: Jetzt bist Du dran!. Festa, Leipzig 2016, ISBN 978-3-865-52502-4, Seite 284 ."},{"text":"„Mit siebzehn hatte sie die Highschool verlassen und dann zwei Jahre ein Jura-Grundstudium in Iowa City absolviert, wohin ihr Stiefvater des Monats, ein Religionslehrer, gezogen war, um seine Studien den Amish zu widmen.“","reference":"James Sallis: Dunkle Vergeltung. Heyne, München 2010, ISBN 978-3-453-43411-0, Seite 77 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Iowa City","id":"b29661f842c60d"},"0069-006f:aa1d37eb60e833":{"word":"ionosphärisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"io·no·sphä·risch","de-DE":"io·no·sphä·risch"},"forms":[{"form":"ionosphärisch","tags":["Positiv"]},{"form":"ionosphärische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ionosphärischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ionosphärischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ionosphärischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"ionosphärisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist ionosphärisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ionosphärisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ionosphärisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind ionosphärisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die Ionosphäre betreffend, zu ihr gehörend"}],"synonyms":[],"origins":["Derivation (Ableitung) zum Stamm des Substantivs Ionosphäre mit dem Derivatem (Ableitungsmorphem) -isch"],"examples":[{"text":"„Ionosphärische Störungen können die Satellitennavigation, die Kommunikation und die Radioastronomie beeinträchtigen.“","reference":"Alina Schadwinkel: Starship-Explosion riss Loch in die obere Atmosphäre. In: Spiegel Online. 3. September 2024, ISSN 0038-7452 (URL, abgerufen am 26. August 2025) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ionosphärisch","id":"aa1d37eb60e833"},"0069-006f:99063a0c5c1392":{"word":"Iona","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Iona","de-DE":"Iona"},"forms":[{"form":"Ionas","tags":["Genitiv","Singular"]},{"form":"des Iona","tags":["Genitiv","Singular"]},{"form":"des Ionas","tags":["Genitiv","Singular"]},{"form":"(das) Iona","tags":["Nominativ","Singular"]},{"form":"(dem) Iona","tags":["Dativ","Singular"]}],"senses":[{"definition":"Insel der Inneren Hebriden in Schottland"}],"synonyms":[],"origins":[],"examples":[{"text":"„›Sie könnte sich in ein spirituelles Zentrum auf der Insel Iona zurückgezogen haben, zu einem gälischen Kleinbauern gezogen sein oder sich in den Kopf gesetzt haben, sämtliche Berge der Munros zu besteigen.‹“","reference":"Ian Rankin: Ehrensache. Goldmann, München 2002, ISBN 978-3-442-45014-5, Seite 117 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Iona","id":"99063a0c5c1392"}};
